window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["HEB"]={"book":"HEB","editions":{"dan-1819":[[1,1,"Efterat Gud fordum havde talet mange Gange og paa mange Maader til Fædrene ved Propheterne, saa haver han i disse sidste Dag talet til os ved Sønnen;","Efterat Gud fordum havde talet mange Gange og paa mange Maader til Fædrene ved Propheterne, saa haver han i disse sidste Dag talet til os ved Sønnen;"],[1,2,"hvem han haver sat til en Arving over alle Ting, ved hvem han og haver gjort Verden;","hvem han haver sat til en Arving over alle Ting, ved hvem han og haver gjort Verden;"],[1,3,"hvilken, efterdi han er hans Herligheds Glands og hans Væsens udtrykte Billede, og bærer alle Ting med sin Kraftes Ord, saa gjorde han ved sig selv vore Synders Renselse, og satte sig hos Majestætens høire Haand i det Høie;","hvilken, efterdi han er hans Herligheds Glands og hans Væsens udtrykte Billede, og bærer alle Ting med sin Kraftes Ord, saa gjorde han ved sig selv vore Synders Renselse, og satte sig hos Majestætens høire Haand i det Høie;"],[1,4,"og han er bleven saa meget ypperligere end Englene, som han haver arvet et herligere Navn fremfor dem.","og han er bleven saa meget ypperligere end Englene, som han haver arvet et herligere Navn fremfor dem."],[1,5,"Thi til hvilken Engel sagde han nogen Tid: du er min Søn, jeg fødte dig i Dag? og atter: jeg skal være ham en Fader, og han skal være mig en Søn?","Thi til hvilken Engel sagde han nogen Tid: du er min Søn, jeg fødte dig i Dag? og atter: jeg skal være ham en Fader, og han skal være mig en Søn?"],[1,6,"Og atter, naar han indfører den Førstefødte i Jorderige, siger han: og alle Guds Engle skulle tilbede ham.","Og atter, naar han indfører den Førstefødte i Jorderige, siger han: og alle Guds Engle skulle tilbede ham."],[1,7,"Om Englene hedder det: han bruger sine Engle som Vinde og sine Tjenere som Ildslue.","Om Englene hedder det: han bruger sine Engle som Vinde og sine Tjenere som Ildslue."],[1,8,"Men til Sønnen: din Throne, o Gud! staaer i al Evighed, Retviishedens Spiir er dit Riges Spiir.","Men til Sønnen: din Throne, o Gud! staaer i al Evighed, Retviishedens Spiir er dit Riges Spiir."],[1,9,"Du elskede Retfærdighed og hadede Uret, derfor haver Gud, din Gud, salvet dig med Glædens Olie fremfor dine Medbrødre.","Du elskede Retfærdighed og hadede Uret, derfor haver Gud, din Gud, salvet dig med Glædens Olie fremfor dine Medbrødre."],[1,10,"Og: du, Herre, grundfæstede Jorden af Begyndelsen, og Himlene ere dine Hænders Gjerninger.","Og: du, Herre, grundfæstede Jorden af Begyndelsen, og Himlene ere dine Hænders Gjerninger."],[1,11,"De skulle forgaae, men du bliver ved; de skulle tilhobe ældes som et Klædebon,","De skulle forgaae, men du bliver ved; de skulle tilhobe ældes som et Klædebon,"],[1,12,"ja som et Klæde skal du sammenrulle dem, og de skulle omskiftes; men du, du er den Samme, og dine Aar skulle ikke aflade.","ja som et Klæde skal du sammenrulle dem, og de skulle omskiftes; men du, du er den Samme, og dine Aar skulle ikke aflade."],[1,13,"Men til hvilken af Englene sagde han nogen Tid: sæt dig hos min høire Haand, indtil jeg lægger dine Fjender til en Skammel for dine Fødder?","Men til hvilken af Englene sagde han nogen Tid: sæt dig hos min høire Haand, indtil jeg lægger dine Fjender til en Skammel for dine Fødder?"],[1,14,"ere de ikke alle Tjenende Aander, udsendte til Hjælp for dem, som skulle arve Salighed?","ere de ikke alle Tjenende Aander, udsendte til Hjælp for dem, som skulle arve Salighed?"],[2,1,"Derfor bør det os desmere at holde fast ved det, vi have hørt, at vi ikke skulle bortrives.","Derfor bør det os desmere at holde fast ved det, vi have hørt, at vi ikke skulle bortrives."],[2,2,"Thi blev det Ord, som var talet ved Engle, haandhævet og fik hver Overtrædelse og Ulydighed sin tilbørlige Løn:","Thi blev det Ord, som var talet ved Engle, haandhævet og fik hver Overtrædelse og Ulydighed sin tilbørlige Løn:"],[2,3,"hvorledes skulle vi da undflye, dersom vi ikke agte saa stor en Salighed? hvilken, efterat den i Begyndelsen var forkyndet ved Herren, er kommen til os, stadfæstet af dem, som havde hørt ham,","hvorledes skulle vi da undflye, dersom vi ikke agte saa stor en Salighed? hvilken, efterat den i Begyndelsen var forkyndet ved Herren, er kommen til os, stadfæstet af dem, som havde hørt ham,"],[2,4,"idet Gud vidnede med, baade ved Tegn og Under og mangehaande kraftige Gjerninger og den Hellig Aands Meddelelser, efter sin Villie.","idet Gud vidnede med, baade ved Tegn og Under og mangehaande kraftige Gjerninger og den Hellig Aands Meddelelser, efter sin Villie."],[2,5,"Thi Engle underlagde han ikke det vordende Jorderige, om hvilket vi tale.","Thi Engle underlagde han ikke det vordende Jorderige, om hvilket vi tale."],[2,6,"Men En haver vidnet etsteds, sigende: hvad er Mennesket, efterdi du kommer ham ihu? eller Menneskets Søn, efterdi du agter paa ham?","Men En haver vidnet etsteds, sigende: hvad er Mennesket, efterdi du kommer ham ihu? eller Menneskets Søn, efterdi du agter paa ham?"],[2,7,"Et Lidet gjorde du ham ringere end Englene; med Ære og Hæder kronede du ham, og satte ham over dine Hænders Gjerninger;","Et Lidet gjorde du ham ringere end Englene; med Ære og Hæder kronede du ham, og satte ham over dine Hænders Gjerninger;"],[2,8,"alle Ting lagde du under hans Fødder. – Idet han altsaa underlagde ham alle Ting, undtog han Intet, som jo er ham underlagt; dog see vi endnu ikke alle Ting at være ham underlagte.","alle Ting lagde du under hans Fødder. – Idet han altsaa underlagde ham alle Ting, undtog han Intet, som jo er ham underlagt; dog see vi endnu ikke alle Ting at være ham underlagte."],[2,9,"Men den, som et Lidet var bleven ringere end Englene, Jesus, see vi formedelst Dødens Lidelse kronet med Ære og Hæder, at han efter Guds naadige Villie skulde smage Døden for Alle.","Men den, som et Lidet var bleven ringere end Englene, Jesus, see vi formedelst Dødens Lidelse kronet med Ære og Hæder, at han efter Guds naadige Villie skulde smage Døden for Alle."],[2,10,"Thi det sømmede ham, for hvem alle Ting ere og ved hvem alle Ting ere, ham, som vilde føre de mange Børn til Herlighed, ved Lidelser at indvie deres Saliggjørelses Stifter.","Thi det sømmede ham, for hvem alle Ting ere og ved hvem alle Ting ere, ham, som vilde føre de mange Børn til Herlighed, ved Lidelser at indvie deres Saliggjørelses Stifter."],[2,11,"Thi baade den, som helliggjør, og de, som helliggjøres, ere alle af Een; hvorfor han ikke skammer sig ved at kalde dem Brødre,","Thi baade den, som helliggjør, og de, som helliggjøres, ere alle af Een; hvorfor han ikke skammer sig ved at kalde dem Brødre,"],[2,12,"sigende: jeg vil forkynde dit Navn for mine Brødre, jeg vil lovsynge dig midt i Menigheden.","sigende: jeg vil forkynde dit Navn for mine Brødre, jeg vil lovsynge dig midt i Menigheden."],[2,13,"Og atter: jeg vil forlade mig paa ham. Og atter: see, her er jeg og de Børn, som Gud haver givet mig.","Og atter: jeg vil forlade mig paa ham. Og atter: see, her er jeg og de Børn, som Gud haver givet mig."],[2,14,"Efterdi da Børnene ere deelagtige i Kjød og Blod, er han iligemaade bleven deelagtig deri, at han ved Døden skulde gjøre den magtesløs, som havde Dødens Vælde, det er Djævelen,","Efterdi da Børnene ere deelagtige i Kjød og Blod, er han iligemaade bleven deelagtig deri, at han ved Døden skulde gjøre den magtesløs, som havde Dødens Vælde, det er Djævelen,"],[2,15,"og befrie dem, saa mange som formedelst Dødens Frygt vare under Trældom al deres Livs Tid.","og befrie dem, saa mange som formedelst Dødens Frygt vare under Trældom al deres Livs Tid."],[2,16,"Thi ingenlunde antager han sig Englene, men Abrahams Sæd antager han sig.","Thi ingenlunde antager han sig Englene, men Abrahams Sæd antager han sig."],[2,17,"Derfor burde han blive sine Brødre lig i alle Ting, at han maatte blive en barmhjertig og trofast Ypperstepræst for Gud, til at forsone Folkets Synder.","Derfor burde han blive sine Brødre lig i alle Ting, at han maatte blive en barmhjertig og trofast Ypperstepræst for Gud, til at forsone Folkets Synder."],[2,18,"Thi efterdi han led og selv blev fristet, kan han komme dem til Hjælp som fristes.","Thi efterdi han led og selv blev fristet, kan han komme dem til Hjælp som fristes."],[3,1,"Derfor, I hellige Brødre, deelagtige i det himmelske Kald! betragter vor Bekjendelses Apostel og Ypperstepræst, Christus Jesus,","Derfor, I hellige Brødre, deelagtige i det himmelske Kald! betragter vor Bekjendelses Apostel og Ypperstepræst, Christus Jesus,"],[3,2,"der var ham tro, som beskikkede ham, ligesom Moses var det i hans ganske Huus.","der var ham tro, som beskikkede ham, ligesom Moses var det i hans ganske Huus."],[3,3,"Thi saa meget større Hæder er han værd fremfor Moses, som den haver større Ære i Huset, der beredte det.","Thi saa meget større Hæder er han værd fremfor Moses, som den haver større Ære i Huset, der beredte det."],[3,4,"Thi hvert Huus beredes af Nogen; men den, som bereder alle Ting, er Gud.","Thi hvert Huus beredes af Nogen; men den, som bereder alle Ting, er Gud."],[3,5,"Og Moses var vel tro i hans ganske Huus som en Tjener, til at vidne hvad der skulde siges,","Og Moses var vel tro i hans ganske Huus som en Tjener, til at vidne hvad der skulde siges,"],[3,6,"men Christus er det som Søn over hans Huus; og hans Huus ere vi, saafremt vi indtil Enden holde fast ved Frimodigheden og det Haab, som er vor Roes.","men Christus er det som Søn over hans Huus; og hans Huus ere vi, saafremt vi indtil Enden holde fast ved Frimodigheden og det Haab, som er vor Roes."],[3,7,"Derfor, som den Hellig Aand siger: i Dag, naar I høre hans Røst,","Derfor, som den Hellig Aand siger: i Dag, naar I høre hans Røst,"],[3,8,"da forhærder ikke Eders Hjerter, som det skete i Forbittrelsen , paa Fristelsens Dag i Ørken,","da forhærder ikke Eders Hjerter, som det skete i Forbittrelsen , paa Fristelsens Dag i Ørken,"],[3,9,"hvor Eders Fædre fristede mig, prøvede mig, enddog de saae mine Gjerninger fyrretyve Aar.","hvor Eders Fædre fristede mig, prøvede mig, enddog de saae mine Gjerninger fyrretyve Aar."],[3,10,"Derfor harmedes jeg paa hiin Slægt og sagde: de fare altid vild i Hjertet, og selv kjende de ikke mine Veie.","Derfor harmedes jeg paa hiin Slægt og sagde: de fare altid vild i Hjertet, og selv kjende de ikke mine Veie."],[3,11,"Saa svoer jeg i min Vrede: sandelig, de skulde ikke indgaae til min Hvile.","Saa svoer jeg i min Vrede: sandelig, de skulde ikke indgaae til min Hvile."],[3,12,"Seer til, Brødre! at der ikke nogensinde i nogen af Eder skal findes et ondt, vantro Hjerte, saa at han affalder fra den levende Gud.","Seer til, Brødre! at der ikke nogensinde i nogen af Eder skal findes et ondt, vantro Hjerte, saa at han affalder fra den levende Gud."],[3,13,"Men formaner Eder selv hver Dag, saalænge det hedder: i Dag, paa det ikke nogen af Eder skal forhærdes ved Syndens Bedrag.","Men formaner Eder selv hver Dag, saalænge det hedder: i Dag, paa det ikke nogen af Eder skal forhærdes ved Syndens Bedrag."],[3,14,"Thi vi ere blevne deelagtige i Christus, saafremt vi bevare vor første Bestandighed fast indtil Enden.","Thi vi ere blevne deelagtige i Christus, saafremt vi bevare vor første Bestandighed fast indtil Enden."],[3,15,"Idet der siges: i Dag, naar I høre hans Røst, de forhærder ikke Eders Hjerter som i Forbittrelsen:","Idet der siges: i Dag, naar I høre hans Røst, de forhærder ikke Eders Hjerter som i Forbittrelsen:"],[3,16,"hvo vare da vel de, som hørte den, og dog forbittrede ham? Mon ikke Alle, som udgik af Ægypten ved Moses?","hvo vare da vel de, som hørte den, og dog forbittrede ham? Mon ikke Alle, som udgik af Ægypten ved Moses?"],[3,17,"Men paa hvilke harmedes han i fyrretyve Aar? Mon ikke paa dem, som syndede, hvis Legemer faldt i Ørken?","Men paa hvilke harmedes han i fyrretyve Aar? Mon ikke paa dem, som syndede, hvis Legemer faldt i Ørken?"],[3,18,"Og hvilke svoer han, at de ikke skulde indgaae til hans Hvile, uden dem, som vare blevne vantroe?","Og hvilke svoer han, at de ikke skulde indgaae til hans Hvile, uden dem, som vare blevne vantroe?"],[3,19,"Vi see altsaa, at de ikke kunde indgaae formedelst Vantroe.","Vi see altsaa, at de ikke kunde indgaae formedelst Vantroe."],[4,1,"Lader os derfor, da Forjættelsen at indgaae til hans Hvile endnu staaer os aaben, vogte os, at ikke Nogen af Eder skulle synes at blive tilbage.","Lader os derfor, da Forjættelsen at indgaae til hans Hvile endnu staaer os aaben, vogte os, at ikke Nogen af Eder skulle synes at blive tilbage."],[4,2,"Thi ogsaa os er Forjættelsen forkyndet, ligesom hine; men Ordet, som de hørte, hjalp dem ikke, fordi det ikke forenede sig med Troen i dem, som hørte det.","Thi ogsaa os er Forjættelsen forkyndet, ligesom hine; men Ordet, som de hørte, hjalp dem ikke, fordi det ikke forenede sig med Troen i dem, som hørte det."],[4,3,"Thi vi indgaae til Hvilen, vi, som troe, efter hvad han haver sagt: saa svoer jeg i min Vrede: sandelig, de skulle ikke indgaae til min Hvile; nemlig efter at Gjerningerne ved Verdens Skabelse vare fuldendte.","Thi vi indgaae til Hvilen, vi, som troe, efter hvad han haver sagt: saa svoer jeg i min Vrede: sandelig, de skulle ikke indgaae til min Hvile; nemlig efter at Gjerningerne ved Verdens Skabelse vare fuldendte."],[4,4,"Thi saaledes haver han et Sted sagt om den syvende Dag: og Gud hvilede paa den syvende Dag fra alle sine Gjerninger.","Thi saaledes haver han et Sted sagt om den syvende Dag: og Gud hvilede paa den syvende Dag fra alle sine Gjerninger."],[4,5,"Og paa dette Sted atter: sandelig, de skulle ikke indgaae til min Hvile.","Og paa dette Sted atter: sandelig, de skulle ikke indgaae til min Hvile."],[4,6,"Efterdi altsaa det er tilbage, at Nogle skulle indgaae til den, og de, hvem Forjættelsen først var forkyndet, ikke kom ind formedelst Vantro:","Efterdi altsaa det er tilbage, at Nogle skulle indgaae til den, og de, hvem Forjættelsen først var forkyndet, ikke kom ind formedelst Vantro:"],[4,7,"saa bestemmer han atter en Dag: i Dag, da han siger ved David efter saa lang en Tid, (som forhen sagt): i Dag naar I høre hans Røst, forhærder ikke Eders Hjerter.","saa bestemmer han atter en Dag: i Dag, da han siger ved David efter saa lang en Tid, (som forhen sagt): i Dag naar I høre hans Røst, forhærder ikke Eders Hjerter."],[4,8,"Thi dersom Josva havde skaffet dem Hvile, da havde han ikke derefter talet om en anden Dag.","Thi dersom Josva havde skaffet dem Hvile, da havde han ikke derefter talet om en anden Dag."],[4,9,"Altsaa er der en Sabbatshvile tilbage for Guds Folk.","Altsaa er der en Sabbatshvile tilbage for Guds Folk."],[4,10,"Thi hvo som er indgaaet til hans Hvile, ogsaa han hviler fra sine Gjerninger, ligesom Gud fra sine.","Thi hvo som er indgaaet til hans Hvile, ogsaa han hviler fra sine Gjerninger, ligesom Gud fra sine."],[4,11,"Lader os derfor beflitte os at komme ind til hiin Hvile, paa det ikke Nogen skal falde efter samme Vantroes Exempel.","Lader os derfor beflitte os at komme ind til hiin Hvile, paa det ikke Nogen skal falde efter samme Vantroes Exempel."],[4,12,"Thi det Guds Ord er levende og kraftigt og skarpere end noget tveegget Sværd, og trænger igjennem, indtil det adskiller baade Sjæl og Aand, baade Ledemod og Marve, og dømmer over Hjertets Tanker og Raad.","Thi det Guds Ord er levende og kraftigt og skarpere end noget tveegget Sværd, og trænger igjennem, indtil det adskiller baade Sjæl og Aand, baade Ledemod og Marve, og dømmer over Hjertets Tanker og Raad."],[4,13,"Og ingen Skabning er usynlig for hans Aasyn; men alle Ting ere blotte og udspændte for hans Øine, om hvem vi tale.","Og ingen Skabning er usynlig for hans Aasyn; men alle Ting ere blotte og udspændte for hans Øine, om hvem vi tale."],[4,14,"Efterdi vi derfor have en stor Ypperstepræst, som er gangen ind i Himlene, Jesus den Guds Søn, da lader os holde fast ved Bekjendelsen.","Efterdi vi derfor have en stor Ypperstepræst, som er gangen ind i Himlene, Jesus den Guds Søn, da lader os holde fast ved Bekjendelsen."],[4,15,"Thi vi have ikke en Ypperstepræst, som ei kan have Medlidenhed med vore Skrøbeligheder, men en saadan, som er forsøgt i alle Ting i lige Maade, dog uden Synd.","Thi vi have ikke en Ypperstepræst, som ei kan have Medlidenhed med vore Skrøbeligheder, men en saadan, som er forsøgt i alle Ting i lige Maade, dog uden Synd."],[4,16,"Derfor lader os træde frem med Frimodighed for Naadens Throne, paa det vi kunne faae Barmhjertighed, og finde Naade til betimelig Hjælp.","Derfor lader os træde frem med Frimodighed for Naadens Throne, paa det vi kunne faae Barmhjertighed, og finde Naade til betimelig Hjælp."],[5,1,"Thi hver Ypperstepræst, som tages af Mennesker, beskikkes for Mennesker til Tjenesten for Gud, at han skal frembære baade Gaver og Slagt-Offere for Synder,","Thi hver Ypperstepræst, som tages af Mennesker, beskikkes for Mennesker til Tjenesten for Gud, at han skal frembære baade Gaver og Slagt-Offere for Synder,"],[5,2,"og kan have Medlidenhed med de Vankundige og Vildfarende, eftersom han og selv er omgiven med Skrøbelighed.","og kan have Medlidenhed med de Vankundige og Vildfarende, eftersom han og selv er omgiven med Skrøbelighed."],[5,3,"Og for dennes Skyld maa han, som for Folket, saaledes og for sig selv, frembære Synd-Offer.","Og for dennes Skyld maa han, som for Folket, saaledes og for sig selv, frembære Synd-Offer."],[5,4,"Og ingen tager sig selv denne Ære, men den, som er kaldet af Gud, ligesom og Aron var.","Og ingen tager sig selv denne Ære, men den, som er kaldet af Gud, ligesom og Aron var."],[5,5,"Saaledes haver ei heller Christus tillagt sig selv den Ære at blive Ypperstepræst, men den, som sagde til ham: du er min Søn, jeg fødte dig i Dag.","Saaledes haver ei heller Christus tillagt sig selv den Ære at blive Ypperstepræst, men den, som sagde til ham: du er min Søn, jeg fødte dig i Dag."],[5,6,"Efter hvad han og siger et andet Sted: du er en Præst til evig Tid, efter Melchisedeks Viis.","Efter hvad han og siger et andet Sted: du er en Præst til evig Tid, efter Melchisedeks Viis."],[5,7,"Han, som i sine Kjøds Dage frembar med stærkt Raab og Taarer Bønner og ydmygelige Begjeringer til den, der var mægtig at frelse ham fra Døden, og blev bønhørt i sin Ængstelse,","Han, som i sine Kjøds Dage frembar med stærkt Raab og Taarer Bønner og ydmygelige Begjeringer til den, der var mægtig at frelse ham fra Døden, og blev bønhørt i sin Ængstelse,"],[5,8,"alligevel han var Søn, lærte dog Lydighed af det, han led;","alligevel han var Søn, lærte dog Lydighed af det, han led;"],[5,9,"og, fuldendet, blev han alle dem, som ham lyde, Aarsag til evig Frelse,","og, fuldendet, blev han alle dem, som ham lyde, Aarsag til evig Frelse,"],[5,10,"udnævnt af Gud til Ypperstepræst efter Melchisedeks Viis.","udnævnt af Gud til Ypperstepræst efter Melchisedeks Viis."],[5,11,"Herom have vi meget at sige, og som er svart at udlægge, efterdi I ere blevne sløve til at fatte.","Herom have vi meget at sige, og som er svart at udlægge, efterdi I ere blevne sløve til at fatte."],[5,12,"Thi skjøndt I efter Tiden endog burde være Lærere, have I atter behov, at man skal lære Eder Begyndelsesgrundene i Guds Ord, og I ere blevne saadanne, som have Mælk behov og ikke haard Føde.","Thi skjøndt I efter Tiden endog burde være Lærere, have I atter behov, at man skal lære Eder Begyndelsesgrundene i Guds Ord, og I ere blevne saadanne, som have Mælk behov og ikke haard Føde."],[5,13,"Hver, som faaer Mælk, er uforfaren i den rette Lære, thi han er et Barn;","Hver, som faaer Mælk, er uforfaren i den rette Lære, thi han er et Barn;"],[5,14,"men for de Fuldkomne er haard Føde, hvilke ved Forfarenhed have øvet Sands til at skjelne mellem Godt og Ondt.","men for de Fuldkomne er haard Føde, hvilke ved Forfarenhed have øvet Sands til at skjelne mellem Godt og Ondt."],[6,1,"Derfor lader os forbigaae Begyndelseslæren om Christus, og skride frem til det Fuldkomnere, at vi ikke atter lægge Grundvolden angaaende Omvendelse fra døde Gjerninger, og Tro paa Gud,","Derfor lader os forbigaae Begyndelseslæren om Christus, og skride frem til det Fuldkomnere, at vi ikke atter lægge Grundvolden angaaende Omvendelse fra døde Gjerninger, og Tro paa Gud,"],[6,2,"og Læren om Daab og Haandspaalæggelse, og de Dødes Opstandelse, og den evige Dom.","og Læren om Daab og Haandspaalæggelse, og de Dødes Opstandelse, og den evige Dom."],[6,3,"Ja, dette ville vi gjøre, dersom Gud det tilsteder.","Ja, dette ville vi gjøre, dersom Gud det tilsteder."],[6,4,"Thi det er umuligt, at de, som eengang ere oplyste, og som have smagt den himmelske Gave, og ere blevne deelagtige i den Hellig Aand,","Thi det er umuligt, at de, som eengang ere oplyste, og som have smagt den himmelske Gave, og ere blevne deelagtige i den Hellig Aand,"],[6,5,"og have smagt Guds gode Ord og den tilkommende Verdens Kræfter, og falde fra, atter kunne fornyes til Omvendelse,","og have smagt Guds gode Ord og den tilkommende Verdens Kræfter, og falde fra, atter kunne fornyes til Omvendelse,"],[6,6,"da de korsfæste sig selv Guds Søn, og gjøre ham til Spot.","da de korsfæste sig selv Guds Søn, og gjøre ham til Spot."],[6,7,"Thi Jorden, som drikker den ofte derpaa faldne Regn og bærer Væxter, tjenlige for dem, som den dyrke, faaer Velsignelse af Gud;","Thi Jorden, som drikker den ofte derpaa faldne Regn og bærer Væxter, tjenlige for dem, som den dyrke, faaer Velsignelse af Gud;"],[6,8,"men den, som bærer Torne og Tidsler, er ubrugbar og Forbandelsen nær; Enden med den er at brændes.","men den, som bærer Torne og Tidsler, er ubrugbar og Forbandelsen nær; Enden med den er at brændes."],[6,9,"Dog, i Henseende til Eder, I Elskelige! ere vi forsikkrede om det Bedre og hvad der bringer Frelse, alligevel vi saaledes tale.","Dog, i Henseende til Eder, I Elskelige! ere vi forsikkrede om det Bedre og hvad der bringer Frelse, alligevel vi saaledes tale."],[6,10,"Thi Gud er ikke uretfærdig, at han skulde forglemme Eders Gjerning og den Kjærlighedens Møie, som I viste for hans Navn, idet I have tjent og tjene de Hellige.","Thi Gud er ikke uretfærdig, at han skulde forglemme Eders Gjerning og den Kjærlighedens Møie, som I viste for hans Navn, idet I have tjent og tjene de Hellige."],[6,11,"Men vi ønske, at enhver af Eder maa vise den samme Nidkjærhed, til fuld Befæstelse i Haabet indtil Enden,","Men vi ønske, at enhver af Eder maa vise den samme Nidkjærhed, til fuld Befæstelse i Haabet indtil Enden,"],[6,12,"saa I ikke blive sendrægtige, men efterfølge dem, som ved Tro og Taalmodighed arvede Forjættelserne.","saa I ikke blive sendrægtige, men efterfølge dem, som ved Tro og Taalmodighed arvede Forjættelserne."],[6,13,"Thi da Gud gav Abraham Forjættelsen, der han ingen Større havde at sværge ved, svoer han ved sig selv, sigende:","Thi da Gud gav Abraham Forjættelsen, der han ingen Større havde at sværge ved, svoer han ved sig selv, sigende:"],[6,14,"sandeligen, jeg vil rigelig velsigne dig og rigelig formere dig.","sandeligen, jeg vil rigelig velsigne dig og rigelig formere dig."],[6,15,"Og saaledes, der han havde ventet taalmodig, bekom han Forjættelsen.","Og saaledes, der han havde ventet taalmodig, bekom han Forjættelsen."],[6,16,"Mennesker sværge jo ved en Større, og Eden er dem en Ende paa al Tvist, til Stadfæstelse.","Mennesker sværge jo ved en Større, og Eden er dem en Ende paa al Tvist, til Stadfæstelse."],[6,17,"Hvorfor, da Gud vilde ydermere vise Forjættelsens Arvinger sit Raads Uforanderlighed, føiede han en Ed dertil,","Hvorfor, da Gud vilde ydermere vise Forjættelsens Arvinger sit Raads Uforanderlighed, føiede han en Ed dertil,"],[6,18,"paa det vi ved to uforanderlige Grunde, efter hvilke det var umuligt, at Gud skulde lyve, kunde have en stærk Trøstegrund, naar vi flye hen at holde fast ved det tilbudne Haab,","paa det vi ved to uforanderlige Grunde, efter hvilke det var umuligt, at Gud skulde lyve, kunde have en stærk Trøstegrund, naar vi flye hen at holde fast ved det tilbudne Haab,"],[6,19,"hvilken vi have som Sjælens trygge og faste Anker, hvilket ogsaa gaaer indenfor Forhænget,","hvilken vi have som Sjælens trygge og faste Anker, hvilket ogsaa gaaer indenfor Forhænget,"],[6,20,"hvor Jesus, vor Forløser, gik ind for os, han, som efter Melchisedeks Viis er bleven en Ypperstepræst til evig Tid.","hvor Jesus, vor Forløser, gik ind for os, han, som efter Melchisedeks Viis er bleven en Ypperstepræst til evig Tid."],[7,1,"Thi denne Melchisedek, Konge i Salem, den høieste Guds Præst, som gik Abraham imøde, der han vendte tilbage fra Kongernes Nederlag, og som velsignede ham,","Thi denne Melchisedek, Konge i Salem, den høieste Guds Præst, som gik Abraham imøde, der han vendte tilbage fra Kongernes Nederlag, og som velsignede ham,"],[7,2,"hvem ogsaa Abraham gav Tiende af Alt: han er først, naar hans Navn udlægges, Retfærdigheds Konge, dernæst ogsaa Salems Konge, det er: Freds Konge;","hvem ogsaa Abraham gav Tiende af Alt: han er først, naar hans Navn udlægges, Retfærdigheds Konge, dernæst ogsaa Salems Konge, det er: Freds Konge;"],[7,3,"uden Fader, uden Moder, uden Slægtregister, havende hverken Dages Begyndelse eller Livs Ende, men lignet med Guds Søn bliver han Præst for stedse.","uden Fader, uden Moder, uden Slægtregister, havende hverken Dages Begyndelse eller Livs Ende, men lignet med Guds Søn bliver han Præst for stedse."],[7,4,"Betragter dog, hvor stor denne er, hvem Patriarchen Abraham endog gav Tiende af Byttet.","Betragter dog, hvor stor denne er, hvem Patriarchen Abraham endog gav Tiende af Byttet."],[7,5,"Nu have vel de af Levi Børn, som annammede Præstedømmet, Befaling at tage Tiende efter Loven af Folket, det er af deres Brødre, alligevel disse ere udkomne af Abrahams Lænd;","Nu have vel de af Levi Børn, som annammede Præstedømmet, Befaling at tage Tiende efter Loven af Folket, det er af deres Brødre, alligevel disse ere udkomne af Abrahams Lænd;"],[7,6,"men den, som ikke regnes i deres Slægt, tog Tiende af Abraham, og velsignede den, som havde Forjættelserne.","men den, som ikke regnes i deres Slægt, tog Tiende af Abraham, og velsignede den, som havde Forjættelserne."],[7,7,"Men uden al Modsigelse velsignes den Ringere af den Ypperligere.","Men uden al Modsigelse velsignes den Ringere af den Ypperligere."],[7,8,"Og her tage dødelige Mennesker Tiende; men der er den, om hvem der vidnes, at han lever.","Og her tage dødelige Mennesker Tiende; men der er den, om hvem der vidnes, at han lever."],[7,9,"Ja, at jeg saa skal sige, endog Levi som, tager Tiende, har ved Abraham givet Tiende;","Ja, at jeg saa skal sige, endog Levi som, tager Tiende, har ved Abraham givet Tiende;"],[7,10,"thi han var endnu i Faderens Lænd, der Melchisedek gik denne imøde.","thi han var endnu i Faderens Lænd, der Melchisedek gik denne imøde."],[7,11,"Hvis der altsaa var Fuldkommelse ved det levitiske Præstedømme, (thi til dette var Folket lovbundet,) hvi gjordes det da ydermere behov, at en anden Præst skulde opstaae efter Melchisedeks Viis, og ikke benævnes efter Aarons Viis?","Hvis der altsaa var Fuldkommelse ved det levitiske Præstedømme, (thi til dette var Folket lovbundet,) hvi gjordes det da ydermere behov, at en anden Præst skulde opstaae efter Melchisedeks Viis, og ikke benævnes efter Aarons Viis?"],[7,12,"Naar Præstedømmet omskiftes, skeer jo og nødvendigen en Omskiftelse af Loven.","Naar Præstedømmet omskiftes, skeer jo og nødvendigen en Omskiftelse af Loven."],[7,13,"Og han, om hvem dette siges, hørte til en anden Stamme, af hvilken Ingen haver taget vare paa Alteret.","Og han, om hvem dette siges, hørte til en anden Stamme, af hvilken Ingen haver taget vare paa Alteret."],[7,14,"Thi det er vitterligt, at vore Herre er oprunden af Juda, for hvilken Stamme Moses Intet haver forordnet om Præstedømmet.","Thi det er vitterligt, at vore Herre er oprunden af Juda, for hvilken Stamme Moses Intet haver forordnet om Præstedømmet."],[7,15,"Og dette bliver end ydermere klart deraf, at der i Lighed med Melchisedek opstaaer en anden Præst,","Og dette bliver end ydermere klart deraf, at der i Lighed med Melchisedek opstaaer en anden Præst,"],[7,16,"som ikke er bleven det efter et kjødeligt Buds Lov, men efter et uopløseligt Livs Kraft.","som ikke er bleven det efter et kjødeligt Buds Lov, men efter et uopløseligt Livs Kraft."],[7,17,"Thi han vidner: du er en Præst evindeligen, efter Melchisedeks Viis.","Thi han vidner: du er en Præst evindeligen, efter Melchisedeks Viis."],[7,18,"Saa skeer da en Afskaffelse af det foregaaende Bud, fordi det var svagt og unyttigt,","Saa skeer da en Afskaffelse af det foregaaende Bud, fordi det var svagt og unyttigt,"],[7,19,"(thi Loven haver Intet fuldkommet,) og en Indførelse af et bedre Haab, ved hvilket vi nærme os til Gud.","(thi Loven haver Intet fuldkommet,) og en Indførelse af et bedre Haab, ved hvilket vi nærme os til Gud."],[7,20,"Og saasom det ikke skete uden Ed,","Og saasom det ikke skete uden Ed,"],[7,21,"(thi hine bleve Præster uden Ed, men denne med Ed, ved den, som siger til ham: Herren haver svoret, og det skal ikke angre ham: du er en Præst evindelig efter Melchisedeks Viis):","(thi hine bleve Præster uden Ed, men denne med Ed, ved den, som siger til ham: Herren haver svoret, og det skal ikke angre ham: du er en Præst evindelig efter Melchisedeks Viis):"],[7,22,"saa er Jesus bleven en saa meget bedre Pagts Borgen.","saa er Jesus bleven en saa meget bedre Pagts Borgen."],[7,23,"Og hine Præster ere blevne mange, fordi Døden formeente dem at vedblive;","Og hine Præster ere blevne mange, fordi Døden formeente dem at vedblive;"],[7,24,"men denne haver et uforgængeligt Præstedømme, fordi han bliver til evig Tid,","men denne haver et uforgængeligt Præstedømme, fordi han bliver til evig Tid,"],[7,25,"hvorfor han og kan fuldkommeligen gjøre dem salige, som komme til Gud formedelst ham, efterdi han lever altid, til at træde frem for dem.","hvorfor han og kan fuldkommeligen gjøre dem salige, som komme til Gud formedelst ham, efterdi han lever altid, til at træde frem for dem."],[7,26,"Thi saadan en Ypperstepræst sømmede os, som er hellig, uden Skyld, ubesmittet, adskilt fra Syndere, og ophøiet over Himlene;","Thi saadan en Ypperstepræst sømmede os, som er hellig, uden Skyld, ubesmittet, adskilt fra Syndere, og ophøiet over Himlene;"],[7,27,"som ikke dagligen haver fornøden, som de andre Ypperstepræster, at frembære Offer først for egne Synder, derefter for Folkets; thi dette gjorde han een Gang for alle, der han offrede sig selv.","som ikke dagligen haver fornøden, som de andre Ypperstepræster, at frembære Offer først for egne Synder, derefter for Folkets; thi dette gjorde han een Gang for alle, der han offrede sig selv."],[7,28,"Thi Loven beskikker til Ypperstepræster Mennesker, som have Skrøbelighed; men Edens Ord, senere end Loven, beskikker Sønnen, for den til evig Tid Fuldkommede.","Thi Loven beskikker til Ypperstepræster Mennesker, som have Skrøbelighed; men Edens Ord, senere end Loven, beskikker Sønnen, for den til evig Tid Fuldkommede."],[8,1,"Saa er da Summen af det, som her siges: vi have en saadan Ypperstepræst, som sidder ved høire Side af Majestætens Throne i Himlene,","Saa er da Summen af det, som her siges: vi have en saadan Ypperstepræst, som sidder ved høire Side af Majestætens Throne i Himlene,"],[8,2,"som er Helligdommens Tjener og det sande Tabernakels, hvilket Herren haver opreist, og ikke et Menneske.","som er Helligdommens Tjener og det sande Tabernakels, hvilket Herren haver opreist, og ikke et Menneske."],[8,3,"Thi hver Ypperstepræst indsættes til at frembære Gaver og Slagt-Offere; derfor er det fornødent, at ogsaa denne maa have Noget, som han kan offre.","Thi hver Ypperstepræst indsættes til at frembære Gaver og Slagt-Offere; derfor er det fornødent, at ogsaa denne maa have Noget, som han kan offre."],[8,4,"Men skulle han være Præst paa Jorden, da var han det aldeles ikke, efterdi der er Præster, som frembære Gaverne efter Loven;","Men skulle han være Præst paa Jorden, da var han det aldeles ikke, efterdi der er Præster, som frembære Gaverne efter Loven;"],[8,5,"hvilke tjene ved Afbildningen og Skyggen af det Himmelske, eftersom det blev Moses af Gud betydet, der han skulde berede Tabernaklet; see til, sagde han, du gjør Alting efter den Lignelse, der blev viist dig paa Bjerget.","hvilke tjene ved Afbildningen og Skyggen af det Himmelske, eftersom det blev Moses af Gud betydet, der han skulde berede Tabernaklet; see til, sagde han, du gjør Alting efter den Lignelse, der blev viist dig paa Bjerget."],[8,6,"Men nu haver han faaet en saa meget ypperligere Tjeneste, som han og er Midler for en bedre Pagt, hvilken er grundet paa bedre Forjættelser.","Men nu haver han faaet en saa meget ypperligere Tjeneste, som han og er Midler for en bedre Pagt, hvilken er grundet paa bedre Forjættelser."],[8,7,"Thi dersom hiin første havde været ulastelig, da var der ikke blevet søgt Sted for en anden.","Thi dersom hiin første havde været ulastelig, da var der ikke blevet søgt Sted for en anden."],[8,8,"Men dadlende siger han til dem: see, de Dage komme, siger Herren, da jeg vil oprette en ny Pagt med Israels Huus og med Judas Huus;","Men dadlende siger han til dem: see, de Dage komme, siger Herren, da jeg vil oprette en ny Pagt med Israels Huus og med Judas Huus;"],[8,9,"ikke efter den Pagt, som jeg gjorde med deres Fædre paa den Dag, der jeg tog dem ved Haanden at udføre dem af Ægyptens Land; thi de bleve ikke i min Pagt, derfor agtede jeg ikke paa dem, siger Herren.","ikke efter den Pagt, som jeg gjorde med deres Fædre paa den Dag, der jeg tog dem ved Haanden at udføre dem af Ægyptens Land; thi de bleve ikke i min Pagt, derfor agtede jeg ikke paa dem, siger Herren."],[8,10,"Men denne er den Pagt, som jeg vil gjøre med Israels Huus efter disse Dage, siger Herren: jeg vil give mine Love i deres Sind, og jeg vil indskrive dem i deres Hjerte; og jeg vil være dem en Gud, og de skulle være mig et Folk.","Men denne er den Pagt, som jeg vil gjøre med Israels Huus efter disse Dage, siger Herren: jeg vil give mine Love i deres Sind, og jeg vil indskrive dem i deres Hjerte; og jeg vil være dem en Gud, og de skulle være mig et Folk."],[8,11,"Og de skulle ikke lære hver sin Næste og hver sin Broder, og sige: kjend Herren; thi de skulle alle kjende mig, fra den Lille iblandt dem indtil den Store iblandt dem.","Og de skulle ikke lære hver sin Næste og hver sin Broder, og sige: kjend Herren; thi de skulle alle kjende mig, fra den Lille iblandt dem indtil den Store iblandt dem."],[8,12,"Thi jeg vil være naadig imod deres Uretfærdigheder, og ikke mere ihukomme deres Synder og deres Overtrædelser.","Thi jeg vil være naadig imod deres Uretfærdigheder, og ikke mere ihukomme deres Synder og deres Overtrædelser."],[8,13,"Idet han siger: en ny, haver han erklæret den første for gammel; men det, som er gammelt og forældet, er nær ved at forsvinde.","Idet han siger: en ny, haver han erklæret den første for gammel; men det, som er gammelt og forældet, er nær ved at forsvinde."],[9,1,"Vel havde ogsaa det første Tabernakel Anordninger for Gudstjenesten og en jordisk Helligdom.","Vel havde ogsaa det første Tabernakel Anordninger for Gudstjenesten og en jordisk Helligdom."],[9,2,"Thi der var indrettet det forreste Tabernakel, hvori Lysestagen var og Bordet og Skuebrødene; dette kaldtes det Hellige.","Thi der var indrettet det forreste Tabernakel, hvori Lysestagen var og Bordet og Skuebrødene; dette kaldtes det Hellige."],[9,3,"Men bag det andet Forhæng var det Tabernakel, som kaldtes det Allerhelligste,","Men bag det andet Forhæng var det Tabernakel, som kaldtes det Allerhelligste,"],[9,4,"som havde det gyldne Røgelsekar og Pagtens Ark, overalt beklædt med Guld, i hvilken var en Guldkrukke med Manna og Aarons blomstrende Stav og Pagtens Tavler.","som havde det gyldne Røgelsekar og Pagtens Ark, overalt beklædt med Guld, i hvilken var en Guldkrukke med Manna og Aarons blomstrende Stav og Pagtens Tavler."],[9,5,"Men ovenover den var Herlighedens Cherubim, som overskyggede Naadestolen, hvorom nu ikke er at tale stykkeviis.","Men ovenover den var Herlighedens Cherubim, som overskyggede Naadestolen, hvorom nu ikke er at tale stykkeviis."],[9,6,"Da nu dette var saaledes indrettet, gik Præsterne altid ind i det forreste Tabernakel, naar de forrettede Tjenesten;","Da nu dette var saaledes indrettet, gik Præsterne altid ind i det forreste Tabernakel, naar de forrettede Tjenesten;"],[9,7,"men i det andet gik den Ypperstepræst alene ind eengang om Aaret, ikke uden Blod, hvilket han offrede for sig selv og Folkets Forseelser,","men i det andet gik den Ypperstepræst alene ind eengang om Aaret, ikke uden Blod, hvilket han offrede for sig selv og Folkets Forseelser,"],[9,8,"hvorved den Hellig Aand gav tilkjende, at Veien til Helligdommen endnu ikke var aabnet, saa længe det første Tabernakel endnu havde sit Stade;","hvorved den Hellig Aand gav tilkjende, at Veien til Helligdommen endnu ikke var aabnet, saa længe det første Tabernakel endnu havde sit Stade;"],[9,9,"hvilket var et Forbillede indtil den nærværende Tid, i hvilken endnu baade Gaver og Offere frembæres,","hvilket var et Forbillede indtil den nærværende Tid, i hvilken endnu baade Gaver og Offere frembæres,"],[9,10,"som ikke formaae fuldkommeligen efter Samvittigheden at hellige den, som forretter Tjenesten, men alene med Hensyn til Mad og Drikke og de adskillige Aftvættelser og kjødelige Anordninger , som vare paalagte indtil Rettelsens Tid.","som ikke formaae fuldkommeligen efter Samvittigheden at hellige den, som forretter Tjenesten, men alene med Hensyn til Mad og Drikke og de adskillige Aftvættelser og kjødelige Anordninger , som vare paalagte indtil Rettelsens Tid."],[9,11,"Men da Christus kom, en Ypperstepræst for det tilkommende Gode, saa gik han igjennem et større og fuldkomnere Tabernakel, hvilket ikke er gjort med Hænder, det er: som ikke er af denne Skabning,","Men da Christus kom, en Ypperstepræst for det tilkommende Gode, saa gik han igjennem et større og fuldkomnere Tabernakel, hvilket ikke er gjort med Hænder, det er: som ikke er af denne Skabning,"],[9,12,"hverken ved Blod af Bukke eller Kalve, men ved sit eget Blod, engang i Helligdommen, og fandt en evig Forløsning.","hverken ved Blod af Bukke eller Kalve, men ved sit eget Blod, engang i Helligdommen, og fandt en evig Forløsning."],[9,13,"Thi dersom Blod af Øxne og Bukke og Asken af en Kvie, hvormed de Urene bestænkes, helliger til Kjødets Reenhed:","Thi dersom Blod af Øxne og Bukke og Asken af en Kvie, hvormed de Urene bestænkes, helliger til Kjødets Reenhed:"],[9,14,"hvor meget mere maa da Christi Blod, som formedelst en evig Aand frembar sig selv som et ulasteligt Offer for Gud, rense Eders Samvittighed fra døde Gjerninger til at tjene den levende Gud.","hvor meget mere maa da Christi Blod, som formedelst en evig Aand frembar sig selv som et ulasteligt Offer for Gud, rense Eders Samvittighed fra døde Gjerninger til at tjene den levende Gud."],[9,15,"Og derfor er han det nye Testamentes Midler, paa det at, da der er skeet en Død til Forløsning fra de Overtrædelser, som vare begangne under det første Testament, de Kaldede maatte faae den evige Arvs Forjættelse.","Og derfor er han det nye Testamentes Midler, paa det at, da der er skeet en Død til Forløsning fra de Overtrædelser, som vare begangne under det første Testament, de Kaldede maatte faae den evige Arvs Forjættelse."],[9,16,"Thi hvor et Testament er, der er det fornødent, at hans Død, som haver gjort Testamentet, skal finde Sted.","Thi hvor et Testament er, der er det fornødent, at hans Død, som haver gjort Testamentet, skal finde Sted."],[9,17,"Thi et Testament bliver først gyldigt ved Døden, efterdi det endnu ikke haver Kraft, medens han lever, som gjorde det.","Thi et Testament bliver først gyldigt ved Døden, efterdi det endnu ikke haver Kraft, medens han lever, som gjorde det."],[9,18,"Derfor blev det første ikke heller indviet uden Blod.","Derfor blev det første ikke heller indviet uden Blod."],[9,19,"Thi der er alle Budene efter Loven af Moses vare forkyndte for alt Folket, tog han Kalve- og Bukkeblod med Vand og Skarlagenuld og Isop, og bestænkede Bogen selv og alt Folket, sigende:","Thi der er alle Budene efter Loven af Moses vare forkyndte for alt Folket, tog han Kalve- og Bukkeblod med Vand og Skarlagenuld og Isop, og bestænkede Bogen selv og alt Folket, sigende:"],[9,20,"dette er den Pagts Blod, hvilken Gud haver villet slutte med Eder.","dette er den Pagts Blod, hvilken Gud haver villet slutte med Eder."],[9,21,"Iligemaade bestænkede han ogsaa Tabernaklet og alle Tjenestens Redskaber med Blodet.","Iligemaade bestænkede han ogsaa Tabernaklet og alle Tjenestens Redskaber med Blodet."],[9,22,"Og næsten Alt bliver efter Loven renset med Blod, og uden Blods Udgydelse skeer ikke Forladelse.","Og næsten Alt bliver efter Loven renset med Blod, og uden Blods Udgydelse skeer ikke Forladelse."],[9,23,"Altsaa var det fornødent, at Afbildningerne af de himmelske Ting skulde renses herved, men de himmelske Ting selv ved bedre Offere end disse.","Altsaa var det fornødent, at Afbildningerne af de himmelske Ting skulde renses herved, men de himmelske Ting selv ved bedre Offere end disse."],[9,24,"Thi Christus gik ikke ind i en Helligdom, gjort med Hænder, som kun er et Billede af det Sande, men i Himlene selv, for nu at aabenbares for Guds Ansigt for os;","Thi Christus gik ikke ind i en Helligdom, gjort med Hænder, som kun er et Billede af det Sande, men i Himlene selv, for nu at aabenbares for Guds Ansigt for os;"],[9,25,"ikke heller, at han flere Gange skulde offre sig selv, ligesom den Ypperstepræst hvert Aar gaaer ind i Helligdommen med fremmed Blod;","ikke heller, at han flere Gange skulde offre sig selv, ligesom den Ypperstepræst hvert Aar gaaer ind i Helligdommen med fremmed Blod;"],[9,26,"(ellers havde han ofte maattet lide fra Verdens Begyndelse;) men nu er han eengang i Tidernes Fuldkommelse aabenbaret for at afskaffe Synden ved sit Offer.","(ellers havde han ofte maattet lide fra Verdens Begyndelse;) men nu er han eengang i Tidernes Fuldkommelse aabenbaret for at afskaffe Synden ved sit Offer."],[9,27,"Og ligesom det er Menneskene beskikket, engang at døe, men derefter Dommen,","Og ligesom det er Menneskene beskikket, engang at døe, men derefter Dommen,"],[9,28,"saaledes er og Christus engang offret for at borttage Manges Synder; anden Gang skal han uden Synd sees af dem, som forvente ham til Saliggjørelse.","saaledes er og Christus engang offret for at borttage Manges Synder; anden Gang skal han uden Synd sees af dem, som forvente ham til Saliggjørelse."],[10,1,"Thi Loven, som haver ikkun en Skygge af de tilkommende Goder og ikke Tingenes Billede selv, kan aldrig ved de samme aarlige Offere, hvilke de bestandigen frembære, fuldkommen forsone dem, som dermed fremkomme.","Thi Loven, som haver ikkun en Skygge af de tilkommende Goder og ikke Tingenes Billede selv, kan aldrig ved de samme aarlige Offere, hvilke de bestandigen frembære, fuldkommen forsone dem, som dermed fremkomme."],[10,2,"Ellers maatte jo disse Offere have ophørt, efterdi de Offrende ikke mere vilde havt nogen Bevidsthed om Synder, naar de eengang vare rensede.","Ellers maatte jo disse Offere have ophørt, efterdi de Offrende ikke mere vilde havt nogen Bevidsthed om Synder, naar de eengang vare rensede."],[10,3,"Men ved Offrene skeer aarligen Syndernes Ihukommelse.","Men ved Offrene skeer aarligen Syndernes Ihukommelse."],[10,4,"Thi det er umuligt, at Blod af Øxne og Bukke kan borttage Synder.","Thi det er umuligt, at Blod af Øxne og Bukke kan borttage Synder."],[10,5,"Derfor siger han, idet han indtræder i Verden: Slagt-Offer og Mad-Offer vilde du ikke, men et Legeme beredte du mig;","Derfor siger han, idet han indtræder i Verden: Slagt-Offer og Mad-Offer vilde du ikke, men et Legeme beredte du mig;"],[10,6,"Brænd-Offere og Synd-Offere havde du ikke Behagelighed til.","Brænd-Offere og Synd-Offere havde du ikke Behagelighed til."],[10,7,"Da sagde jeg, see, jeg kommer, (der er skrevet om mig i Bogens Rolle,) for at gjøre, Gud! din Villie.","Da sagde jeg, see, jeg kommer, (der er skrevet om mig i Bogens Rolle,) for at gjøre, Gud! din Villie."],[10,8,"Men da han først havde sagt: Slagt-Offer og Mad-Offer og Brænd-Offere og Synd-Offere vilde du ikke havde, ei heller Behagelighed til dem, (og disse frembæres efter Loven,)","Men da han først havde sagt: Slagt-Offer og Mad-Offer og Brænd-Offere og Synd-Offere vilde du ikke havde, ei heller Behagelighed til dem, (og disse frembæres efter Loven,)"],[10,9,"saa siger han: see, jeg kommer, for at gjøre, Gud! din Villie. (han ophæver det Første for at sætte det Andet.)","saa siger han: see, jeg kommer, for at gjøre, Gud! din Villie. (han ophæver det Første for at sætte det Andet.)"],[10,10,"Ved hvilken Villie vi ere helliggjorte formedelst Jesu Christi Legemes Offrelse den ene Gang.","Ved hvilken Villie vi ere helliggjorte formedelst Jesu Christi Legemes Offrelse den ene Gang."],[10,11,"Og hver Præst staaer daglig for at tjene og for at offre mange Gange de samme Offere, hvilke aldrig kunne borttage Synder.","Og hver Præst staaer daglig for at tjene og for at offre mange Gange de samme Offere, hvilke aldrig kunne borttage Synder."],[10,12,"Men han, der han havde offret eet Offer for Syndere, sidder han for stedse hos Guds høire Haand,","Men han, der han havde offret eet Offer for Syndere, sidder han for stedse hos Guds høire Haand,"],[10,13,"biende iøvrigt, indtil hans Fjender blive lagte til hans Fødders Fodskammel.","biende iøvrigt, indtil hans Fjender blive lagte til hans Fødders Fodskammel."],[10,14,"Thi med eet Offer haver han for stedse fuldkommen forsonet dem, som helliggjøres.","Thi med eet Offer haver han for stedse fuldkommen forsonet dem, som helliggjøres."],[10,15,"Dette vidner ogsaa den Hellig Aand for os; thi efter først at have sagt:","Dette vidner ogsaa den Hellig Aand for os; thi efter først at have sagt:"],[10,16,"denne er den Pagt, som jeg vil gjøre med dem efter disse Dage, siger Herren: jeg vil give mine Love i deres Hjerter og skrive dem i deres Sind;","denne er den Pagt, som jeg vil gjøre med dem efter disse Dage, siger Herren: jeg vil give mine Love i deres Hjerter og skrive dem i deres Sind;"],[10,17,"da siger han: og jeg vil ikke mere ihukomme deres Synder og deres Overtrædelser.","da siger han: og jeg vil ikke mere ihukomme deres Synder og deres Overtrædelser."],[10,18,"Men hvor disse ere forladte, der behøves ikke mere Offer for Synden.","Men hvor disse ere forladte, der behøves ikke mere Offer for Synden."],[10,19,"Efterdi vi da, Brødre! have Frihed til at indgaae i Helligdommen ved Jesu Blod,","Efterdi vi da, Brødre! have Frihed til at indgaae i Helligdommen ved Jesu Blod,"],[10,20,"hvortil han indviede os en ny og levende Vei gjennem Forhænget, det er, hans Kjød,","hvortil han indviede os en ny og levende Vei gjennem Forhænget, det er, hans Kjød,"],[10,21,"og efterdi vi have en stor Præst over Guds Huus:","og efterdi vi have en stor Præst over Guds Huus:"],[10,22,"da lader os træde frem med et sanddru Hjerte, i Troens fulde Forvisning, Hjerterne ved Bestænkelsen rensede fra en ond Samvittighed, og Legemet aftvættet med reent Vand.","da lader os træde frem med et sanddru Hjerte, i Troens fulde Forvisning, Hjerterne ved Bestænkelsen rensede fra en ond Samvittighed, og Legemet aftvættet med reent Vand."],[10,23,"Lader os holde fast ved Haabets urokkelige Bekjendelse; thi han er trofast, som gav Forjættelsen;","Lader os holde fast ved Haabets urokkelige Bekjendelse; thi han er trofast, som gav Forjættelsen;"],[10,24,"og lader os give Agt paa hverandre, saa vi opmuntre hverandre til Kjærlighed og gode Gjerninger,","og lader os give Agt paa hverandre, saa vi opmuntre hverandre til Kjærlighed og gode Gjerninger,"],[10,25,"og ikke forlade vor egen Forsamling, som Nogle have for Skik, men formane hverandre, og det saa meget desmere, som I see, at Dagen nærmer sig.","og ikke forlade vor egen Forsamling, som Nogle have for Skik, men formane hverandre, og det saa meget desmere, som I see, at Dagen nærmer sig."],[10,26,"Thi synde vi med Villie, efter at have annammet Sandhedens Erkjendelse, er der ikke Offer mere tilbage for Synden,","Thi synde vi med Villie, efter at have annammet Sandhedens Erkjendelse, er der ikke Offer mere tilbage for Synden,"],[10,27,"Men en frygtelig Forventelse af Dommen og en brændende Nidkjærhed, som skal fortære de Gjenstridige.","Men en frygtelig Forventelse af Dommen og en brændende Nidkjærhed, som skal fortære de Gjenstridige."],[10,28,"Naar Nogen haver brudt Mose Lov, døer han uden Barmhjertighed, efter to eller tre Vidners Udsagn:","Naar Nogen haver brudt Mose Lov, døer han uden Barmhjertighed, efter to eller tre Vidners Udsagn:"],[10,29,"hvormeget værre Straf, mene I at den skal agtes værd, som træder Guds Søn med Fødder, og ringeagter Pagtens Blod, hvormed han var helliget, og forhaaner Naadens Aand?","hvormeget værre Straf, mene I at den skal agtes værd, som træder Guds Søn med Fødder, og ringeagter Pagtens Blod, hvormed han var helliget, og forhaaner Naadens Aand?"],[10,30,"Thi vi kjende den, som haver sagt: mig hører Hevnen til, jeg vil betale, siger Herren; og atter: Herren skal dømme sit Folk.","Thi vi kjende den, som haver sagt: mig hører Hevnen til, jeg vil betale, siger Herren; og atter: Herren skal dømme sit Folk."],[10,31,"Det er forfærdeligt at falde i den levende Guds Hænder.","Det er forfærdeligt at falde i den levende Guds Hænder."],[10,32,"Kommer de forrige Dage ihu, i hvilke I, efterat I vare blevne oplyste, udholdt en stor Kamp mod Lidelser,","Kommer de forrige Dage ihu, i hvilke I, efterat I vare blevne oplyste, udholdt en stor Kamp mod Lidelser,"],[10,33,"idet I deels selv ved Forsmædelser og Trængsler bleve et Skuespil, deels toge Deel med dem, som fristede saadanne Kaar.","idet I deels selv ved Forsmædelser og Trængsler bleve et Skuespil, deels toge Deel med dem, som fristede saadanne Kaar."],[10,34,"Thi baade have I Medlidenhed med mine Baand, og I skikkede Eder med Glæde deri, at man røvede Eders Gods, vidende, at I have i Eder selv et bedre og blivende Gods i Himlene.","Thi baade have I Medlidenhed med mine Baand, og I skikkede Eder med Glæde deri, at man røvede Eders Gods, vidende, at I have i Eder selv et bedre og blivende Gods i Himlene."],[10,35,"Kaster derfor ikke Eders Frimodighed bort, hvilken haver en stor Belønning;","Kaster derfor ikke Eders Frimodighed bort, hvilken haver en stor Belønning;"],[10,36,"thi I have Taalmodighed behov, at, naar I have gjort Guds Villie, I da kunne faae Forjættelsen.","thi I have Taalmodighed behov, at, naar I have gjort Guds Villie, I da kunne faae Forjættelsen."],[10,37,"Thi der er endnu kun en liden Stund, indtil den kommer, der skal komme, og han skal ikke tøve.","Thi der er endnu kun en liden Stund, indtil den kommer, der skal komme, og han skal ikke tøve."],[10,38,"Men den Retfærdige af Troen skal leve; og dersom Nogen uddrager sig, haver min Sjæl ikke Behagelighed i ham.","Men den Retfærdige af Troen skal leve; og dersom Nogen uddrager sig, haver min Sjæl ikke Behagelighed i ham."],[10,39,"Men vi ere ikke af dem, som unddrage sig til deres Fordærvelse, men af dem, som troe til Sjælens Frelse.","Men vi ere ikke af dem, som unddrage sig til deres Fordærvelse, men af dem, som troe til Sjælens Frelse."],[11,1,"Men Troen er en Bestandighed i det, som haabes, en fast Overbeviisning om det, som ikke sees.","Men Troen er en Bestandighed i det, som haabes, en fast Overbeviisning om det, som ikke sees."],[11,2,"Ved den fik de Gamle godt Vidnesbyrd.","Ved den fik de Gamle godt Vidnesbyrd."],[11,3,"Ved Tro forstaae vi, at Verden er bleven beredt ved Guds Ord, saa at de Ting, som sees, ere blevne af dem, der ikke vare tilsyne.","Ved Tro forstaae vi, at Verden er bleven beredt ved Guds Ord, saa at de Ting, som sees, ere blevne af dem, der ikke vare tilsyne."],[11,4,"Formedelst Tro offrede Abel Gud et bedre Offer end Cain, og for den fik han det Vidnesbyrd, at han var retfærdig, idet Gud bevidnede sit Velbehag i hans Gaver; og ved den taler han endnu, alligevel han er død.","Formedelst Tro offrede Abel Gud et bedre Offer end Cain, og for den fik han det Vidnesbyrd, at han var retfærdig, idet Gud bevidnede sit Velbehag i hans Gaver; og ved den taler han endnu, alligevel han er død."],[11,5,"Formedelst Tro blev Enoch borttagen, at han ikke skulde see Døden og blev ikke funden, efterdi Gud havde taget ham bort; thi før han blev borttagen, havde han det Vidnesbyrd, at han behagede Gud.","Formedelst Tro blev Enoch borttagen, at han ikke skulde see Døden og blev ikke funden, efterdi Gud havde taget ham bort; thi før han blev borttagen, havde han det Vidnesbyrd, at han behagede Gud."],[11,6,"Men uden Tro er det umuligt at behage ham; thi det bør den, som kommer frem for Gud, at troe, at han er til, og at han bliver deres Belønner, som søge ham.","Men uden Tro er det umuligt at behage ham; thi det bør den, som kommer frem for Gud, at troe, at han er til, og at han bliver deres Belønner, som søge ham."],[11,7,"Formedelst Tro var det, at Noah, advaret af Gud om det, som endnu ikke faaes, frygtede Gud, og beredte Arken til sit Huses Frelse; ved den fordømte han Verden, og blev Arving til Retfærdigheden af Troen.","Formedelst Tro var det, at Noah, advaret af Gud om det, som endnu ikke faaes, frygtede Gud, og beredte Arken til sit Huses Frelse; ved den fordømte han Verden, og blev Arving til Retfærdigheden af Troen."],[11,8,"Formedelst Tro var Abraham lydig, der han blev kaldet, i at udgaae til det Sted, som han skulde tage til Arv; og han gik ud, dog han ikke vidste, hvor han kom.","Formedelst Tro var Abraham lydig, der han blev kaldet, i at udgaae til det Sted, som han skulde tage til Arv; og han gik ud, dog han ikke vidste, hvor han kom."],[11,9,"Formedelst Tro opholdt han sig i Forjættelsens Land, som i et fremmed, boende udi Pauluner med Isaak og Jakob, som vare Medarvinger til samme Forjættelse;","Formedelst Tro opholdt han sig i Forjættelsens Land, som i et fremmed, boende udi Pauluner med Isaak og Jakob, som vare Medarvinger til samme Forjættelse;"],[11,10,"thi han forventede den Stad, som haver Grundvold, hvis Bygmester og Forarbeider er Gud.","thi han forventede den Stad, som haver Grundvold, hvis Bygmester og Forarbeider er Gud."],[11,11,"Formedelst Tro fik selv Sara Kraft til at undfange, og fødte over hendes Alders Tid; thi hun agtede ham at være trofast, som havde lovet det.","Formedelst Tro fik selv Sara Kraft til at undfange, og fødte over hendes Alders Tid; thi hun agtede ham at være trofast, som havde lovet det."],[11,12,"Derfor avledes og af Een, og det en Kraftesløs, som Stjernerne paa Himmelen i Mangfoldighed og som Sandet ved Havets Bred, det utallige.","Derfor avledes og af Een, og det en Kraftesløs, som Stjernerne paa Himmelen i Mangfoldighed og som Sandet ved Havets Bred, det utallige."],[11,13,"I Tro døde alle disse, uden at have opnaaet Forjættelserne, men saae dem langt borte, og lode sig overbevise, og hilsede dem, og bekjendte, at de vare Gjester og Udlændinge paa Jorden.","I Tro døde alle disse, uden at have opnaaet Forjættelserne, men saae dem langt borte, og lode sig overbevise, og hilsede dem, og bekjendte, at de vare Gjester og Udlændinge paa Jorden."],[11,14,"Men de, som sige Saadant, give klarligen tilkjende, at de søge et Fædreneland.","Men de, som sige Saadant, give klarligen tilkjende, at de søge et Fædreneland."],[11,15,"Og dersom de havde havt det i Tanker, hvorfra de vare udgangne, havde de vel havt Tid at vende tilbage;","Og dersom de havde havt det i Tanker, hvorfra de vare udgangne, havde de vel havt Tid at vende tilbage;"],[11,16,"men nu hige de efter et bedre, det er et himmelsk; derfor blues Gud ikke ved dem, at kaldes deres Gud; thi han haver beredt dem en Stad.","men nu hige de efter et bedre, det er et himmelsk; derfor blues Gud ikke ved dem, at kaldes deres Gud; thi han haver beredt dem en Stad."],[11,17,"Formedelst Tro offrede Abraham Isaak, der han fristedes, ja den Eenbaarne offrede han, som havde annammet Forjættelserne,","Formedelst Tro offrede Abraham Isaak, der han fristedes, ja den Eenbaarne offrede han, som havde annammet Forjættelserne,"],[11,18,"til hvem der var sagt: i Isaak skal Sæd fremkaldes dig:","til hvem der var sagt: i Isaak skal Sæd fremkaldes dig:"],[11,19,"thi han betænkte, at Gud var mægtig endog til at opreise fra de Døde, og i en Lighed dermed fik han ham ogsaa tilbage.","thi han betænkte, at Gud var mægtig endog til at opreise fra de Døde, og i en Lighed dermed fik han ham ogsaa tilbage."],[11,20,"Formedelst Tro om det Tilkommende velsignede Isaak Jakob og Esau.","Formedelst Tro om det Tilkommende velsignede Isaak Jakob og Esau."],[11,21,"Formedelst Tro velsignede Jakob, der han døde, hver af Josephs Sønner, og tilbad, lænende sig over sin Stav.","Formedelst Tro velsignede Jakob, der han døde, hver af Josephs Sønner, og tilbad, lænende sig over sin Stav."],[11,22,"Formedelst Tro erindrede Joseph døende Israels Børns Udgang, og gav Befaling om sine Been.","Formedelst Tro erindrede Joseph døende Israels Børns Udgang, og gav Befaling om sine Been."],[11,23,"Formedelst Tro blev Moses, der han var født, skjult tre Maaneder af sine Forældre, fordi de saae, at Barnet var deiligt, og de frygtede ikke for Kongens Befaling.","Formedelst Tro blev Moses, der han var født, skjult tre Maaneder af sine Forældre, fordi de saae, at Barnet var deiligt, og de frygtede ikke for Kongens Befaling."],[11,24,"Formedelst Tro negtede Moses, der han var bleven stor, at kaldes Pharaos Datters Søn,","Formedelst Tro negtede Moses, der han var bleven stor, at kaldes Pharaos Datters Søn,"],[11,25,"og valgte heller at lide Ondt med Guds Folk, end at have Syndens timelige Nydelse,","og valgte heller at lide Ondt med Guds Folk, end at have Syndens timelige Nydelse,"],[11,26,"agtende Christi Forsmædelse for større Rigdom end Ægyptens Liggendefæ; thi han saae hen til Belønningen.","agtende Christi Forsmædelse for større Rigdom end Ægyptens Liggendefæ; thi han saae hen til Belønningen."],[11,27,"Formedelst Tro forlod han Ægypten og frygtede ikke for Kongens Vrede; thi han holdt hardt ved den Usynlige, som om han saae ham.","Formedelst Tro forlod han Ægypten og frygtede ikke for Kongens Vrede; thi han holdt hardt ved den Usynlige, som om han saae ham."],[11,28,"Formedelst Tro anordnede han Paasken og Blodsbestænkelsen, at den, som ødelagde de Førstefødte, skulde ikke røre dem.","Formedelst Tro anordnede han Paasken og Blodsbestænkelsen, at den, som ødelagde de Førstefødte, skulde ikke røre dem."],[11,29,"Formedelst Tro gik de igjennem det røde Hav, som igjennem tørt Land; men da Ægypterne forsøgte det, druknede de.","Formedelst Tro gik de igjennem det røde Hav, som igjennem tørt Land; men da Ægypterne forsøgte det, druknede de."],[11,30,"Formedelst Tro faldt Jerichos Mure, efterat de vare omgangne i syv Dage.","Formedelst Tro faldt Jerichos Mure, efterat de vare omgangne i syv Dage."],[11,31,"Formedelst Tro omkom Rahab, Skjøgen, ikke med de Vantroe; thi hun annammede Speiderne med Fred.","Formedelst Tro omkom Rahab, Skjøgen, ikke med de Vantroe; thi hun annammede Speiderne med Fred."],[11,32,"Dog hvi skal jeg tale mere? Tiden vilde jo fattes mig, hvis jeg fortalte om Gideon, om Barak, og Samson og Jephta, om David og Samuel og Propheterne,","Dog hvi skal jeg tale mere? Tiden vilde jo fattes mig, hvis jeg fortalte om Gideon, om Barak, og Samson og Jephta, om David og Samuel og Propheterne,"],[11,33,"hvilke formedelst Tro overvandt Riger, øvede Retfærdighed, erholdt Forjættelser, stoppede Løvers Mund,","hvilke formedelst Tro overvandt Riger, øvede Retfærdighed, erholdt Forjættelser, stoppede Løvers Mund,"],[11,34,"slukte Ildens Kraft, undflyede Sværdets Od, bleve stærke efter Skrøbelighed, bleve vældige i Krigen, bragte Fjendernes Leire til at vige.","slukte Ildens Kraft, undflyede Sværdets Od, bleve stærke efter Skrøbelighed, bleve vældige i Krigen, bragte Fjendernes Leire til at vige."],[11,35,"Kvinder fik deres Døde igjen, opstandne; Andre bleve udspilede til Pinsel og toge ikke mod Befrielse, at de maatte erholde en herligere Opstandelse.","Kvinder fik deres Døde igjen, opstandne; Andre bleve udspilede til Pinsel og toge ikke mod Befrielse, at de maatte erholde en herligere Opstandelse."],[11,36,"Andre prøvede Bespottelser og Hudstrygelser, tilmed Lænker og Fængsel;","Andre prøvede Bespottelser og Hudstrygelser, tilmed Lænker og Fængsel;"],[11,37,"de bleve stenede, gjennemsaugede, fristede, henrettede med Sværd, gik omkring i Faare- og Gedeskind, lidende Mangel, betrængte, mishandlede,","de bleve stenede, gjennemsaugede, fristede, henrettede med Sværd, gik omkring i Faare- og Gedeskind, lidende Mangel, betrængte, mishandlede,"],[11,38,"(dem var Verden ikke værd,) omvankende i Ørkener, paa Bjerge og i Jordens Huler og Kløfter.","(dem var Verden ikke værd,) omvankende i Ørkener, paa Bjerge og i Jordens Huler og Kløfter."],[11,39,"Og disse alle, enddog de havde Vidnesbyrd for deres Tro, naaede ikke Forjættelsen,","Og disse alle, enddog de havde Vidnesbyrd for deres Tro, naaede ikke Forjættelsen,"],[11,40,"efterdi Gud havde udseet noget Bedre for os, at de ikke skulde fuldkommes uden os.","efterdi Gud havde udseet noget Bedre for os, at de ikke skulde fuldkommes uden os."],[12,1,"Derfor lader og os, efterdi vi have en saadan Skare af Vidner omkring os, aflægge al Byrde og Synden, som lettelig forrasker os, og med Standhaftighed gjennemløbe den os anviste Bane,","Derfor lader og os, efterdi vi have en saadan Skare af Vidner omkring os, aflægge al Byrde og Synden, som lettelig forrasker os, og med Standhaftighed gjennemløbe den os anviste Bane,"],[12,2,"idet vi see hen til Troens Begynder og Fuldkommer, Jesus, hvilken istedetfor den Glæde, han havde for sig, led taalmodeligen Korset, idet han foragtede Forhaanelsen, og sidder nu ved den høire Side af Guds Throne.","idet vi see hen til Troens Begynder og Fuldkommer, Jesus, hvilken istedetfor den Glæde, han havde for sig, led taalmodeligen Korset, idet han foragtede Forhaanelsen, og sidder nu ved den høire Side af Guds Throne."],[12,3,"Betragter den, som haver taalmodeligen lidt en saadan Modsigelse af Syndere imod sig, at I ikke blive trætte og forsage i Eders Sjæle.","Betragter den, som haver taalmodeligen lidt en saadan Modsigelse af Syndere imod sig, at I ikke blive trætte og forsage i Eders Sjæle."],[12,4,"Endnu stode I ikke imod indtil Blodet, idet I strede imod Synden,","Endnu stode I ikke imod indtil Blodet, idet I strede imod Synden,"],[12,5,"og I have glemt den Formaning, der taler til Eder som til Børn: min Søn! agt ikke Herrens Revselse ringe, vær ikke heller forsagt, naar du tugtes af ham;","og I have glemt den Formaning, der taler til Eder som til Børn: min Søn! agt ikke Herrens Revselse ringe, vær ikke heller forsagt, naar du tugtes af ham;"],[12,6,"thi hvem Herren elsker, den revser han, og han tugter haardeligen hver Søn, som han antager sig.","thi hvem Herren elsker, den revser han, og han tugter haardeligen hver Søn, som han antager sig."],[12,7,"Dersom I lide Revselse, handler Gud med Eder, som med Børn; thi hvo er den Søn, som Faderen ikke revser?","Dersom I lide Revselse, handler Gud med Eder, som med Børn; thi hvo er den Søn, som Faderen ikke revser?"],[12,8,"Men dersom I ere uden Revselse, i hvilken Alle ere blevne deelagtige, da ere I uægte, og ikke Børn.","Men dersom I ere uden Revselse, i hvilken Alle ere blevne deelagtige, da ere I uægte, og ikke Børn."],[12,9,"Have vi tilmed havt vore kjødelige Fædre til Optugtere og bevaret Frygt for dem, skulde vi da ikke meget mere være Aandernes Fader underdanige, og leve?","Have vi tilmed havt vore kjødelige Fædre til Optugtere og bevaret Frygt for dem, skulde vi da ikke meget mere være Aandernes Fader underdanige, og leve?"],[12,10,"Thi hine revsede os for faa Dage efter deres Tykke, men han revser os til Nytte, paa det vi skulle blive deelagtige i hans Hellighed.","Thi hine revsede os for faa Dage efter deres Tykke, men han revser os til Nytte, paa det vi skulle blive deelagtige i hans Hellighed."],[12,11,"Men al Revselse, imedens den er nærværende, synes ikke at være til Glæde, men til Bedrøvelse; men siden giver den igjen dem, som derved ere øvede, Retfærdigheds salige Frugt.","Men al Revselse, imedens den er nærværende, synes ikke at være til Glæde, men til Bedrøvelse; men siden giver den igjen dem, som derved ere øvede, Retfærdigheds salige Frugt."],[12,12,"Derfor retter de slappe Hænder og de afmægtige Knæ,","Derfor retter de slappe Hænder og de afmægtige Knæ,"],[12,13,"og gjører sikkre Trin med Eders Fødder, at ikke de Halte skal drages mere af Lave, men snarere helbredes.","og gjører sikkre Trin med Eders Fødder, at ikke de Halte skal drages mere af Lave, men snarere helbredes."],[12,14,"Stræber efter Fred med hver Mand, og efter Hellighed, uden hvilken Ingen skal see Herren;","Stræber efter Fred med hver Mand, og efter Hellighed, uden hvilken Ingen skal see Herren;"],[12,15,"og seer til, at ikke Nogen forsømmer Guds Naades Tid, at ikke nogen bitter Rod skyder op og gjør Forvirring, saa at mange ved den smittes;","og seer til, at ikke Nogen forsømmer Guds Naades Tid, at ikke nogen bitter Rod skyder op og gjør Forvirring, saa at mange ved den smittes;"],[12,16,"at ikke Nogen er en Skjørlevner eller en Vanhellig, som Esau, som for een Ret Mad afhændede sin Førstefødsels-Rettighed.","at ikke Nogen er en Skjørlevner eller en Vanhellig, som Esau, som for een Ret Mad afhændede sin Førstefødsels-Rettighed."],[12,17,"Thi I vide, at han og derefter, der han vilde arve Velsignelsen, blev forskudt; thi han fandt ikke Sted for sin Anger, alligevel han med Graad søgte derom.","Thi I vide, at han og derefter, der han vilde arve Velsignelsen, blev forskudt; thi han fandt ikke Sted for sin Anger, alligevel han med Graad søgte derom."],[12,18,"I ere jo ikke komne til hiint bævende Bjerg, antændt af Ild, og til Mulm og Mørke og Uveir,","I ere jo ikke komne til hiint bævende Bjerg, antændt af Ild, og til Mulm og Mørke og Uveir,"],[12,19,"og til Basunens Lyd og til Ordenes Røst, hvorom de, der hørte den, bade, at der ikke mere maatte tales til dem.","og til Basunens Lyd og til Ordenes Røst, hvorom de, der hørte den, bade, at der ikke mere maatte tales til dem."],[12,20,"Thi de fordroge ikke det, som var budet, at endog, dersom et Dyr rørte ved Bjerget, skulde det stenes eller fældes med et Pileskud.","Thi de fordroge ikke det, som var budet, at endog, dersom et Dyr rørte ved Bjerget, skulde det stenes eller fældes med et Pileskud."],[12,21,"Og saa frygteligt var Synet, at Moses sagde: jeg er forfærdet og bæver.","Og saa frygteligt var Synet, at Moses sagde: jeg er forfærdet og bæver."],[12,22,"Men I ere komne til Zions Bjerg og til den levende Guds Stad, til det himmelske Jerusalem og til Englenes mange Tusinde,","Men I ere komne til Zions Bjerg og til den levende Guds Stad, til det himmelske Jerusalem og til Englenes mange Tusinde,"],[12,23,"til de Førstefødtes Forsamling og Menighed, som ere opskrevne i Himlene, og til Gud, Alles Dommer, og til de fuldkommede Retfærdiges Aander,","til de Førstefødtes Forsamling og Menighed, som ere opskrevne i Himlene, og til Gud, Alles Dommer, og til de fuldkommede Retfærdiges Aander,"],[12,24,"og til den nye Pagts Midler, Jesus, og til Bestænkelsens Blod, som taler bedre end Abel.","og til den nye Pagts Midler, Jesus, og til Bestænkelsens Blod, som taler bedre end Abel."],[12,25,"Vogter Eder, at I ikke forskyde den, som taler. Thi undflyede de ikke, som forskøde ham, der talede Guds Ord paa Jorden, da skulle vi meget mindre, dersom vi ere gjenstridige mod ham fra Himlene,","Vogter Eder, at I ikke forskyde den, som taler. Thi undflyede de ikke, som forskøde ham, der talede Guds Ord paa Jorden, da skulle vi meget mindre, dersom vi ere gjenstridige mod ham fra Himlene,"],[12,26,"hvis Røst da bevægede Jorden; men nu har han lovet, sigende: endnu eengang ryster jeg, ikke aleneste Jorden, men og Himmelen.","hvis Røst da bevægede Jorden; men nu har han lovet, sigende: endnu eengang ryster jeg, ikke aleneste Jorden, men og Himmelen."],[12,27,"Men dette, endnu eengang, giver tilkjende, at de Ting, der bevæges, skulle omskiftes, efterdi de ere gjorte, paa det de, der ikke bevæges, skulle blive ved.","Men dette, endnu eengang, giver tilkjende, at de Ting, der bevæges, skulle omskiftes, efterdi de ere gjorte, paa det de, der ikke bevæges, skulle blive ved."],[12,28,"Efterdi vi da have bekommet et ubevægeligt Rige, saa lader os holde fast ved Naaden, ved hvilken vi kunde tjene Gud velbehagligen, med Undseelse og Ærefrygt.","Efterdi vi da have bekommet et ubevægeligt Rige, saa lader os holde fast ved Naaden, ved hvilken vi kunde tjene Gud velbehagligen, med Undseelse og Ærefrygt."],[12,29,"Thi og vor Gud er en fortærende Ild.","Thi og vor Gud er en fortærende Ild."],[13,1,"Broderkjærligheden blive ved!","Broderkjærligheden blive ved!"],[13,2,"Glemmer ikke Gjestfrihed; thi ved den have Nogle, uden at vide det, herbergeret Engle.","Glemmer ikke Gjestfrihed; thi ved den have Nogle, uden at vide det, herbergeret Engle."],[13,3,"Kommer de Bundne ihu, som selv medbundne; dem, der lide ilde, som de, der og selv ere i Legemet.","Kommer de Bundne ihu, som selv medbundne; dem, der lide ilde, som de, der og selv ere i Legemet."],[13,4,"Ægteskabet være hæderligt hos Alle, og Ægtesengen ubesmittet; men Skjørlevnere og Hoerkarle skal Gud dømme.","Ægteskabet være hæderligt hos Alle, og Ægtesengen ubesmittet; men Skjørlevnere og Hoerkarle skal Gud dømme."],[13,5,"Eders Vandel være uden Gjerrighed, nøies med det, I have; thi han haver selv sagt; jeg vil ingenlunde slippe dig og ingenlunde forlade dig,","Eders Vandel være uden Gjerrighed, nøies med det, I have; thi han haver selv sagt; jeg vil ingenlunde slippe dig og ingenlunde forlade dig,"],[13,6,"saa at vi kunne sige med frit Mod: Herren er min Hjælper, jeg vil ikke frygte; hvad kan et Menneske gjøre mig?","saa at vi kunne sige med frit Mod: Herren er min Hjælper, jeg vil ikke frygte; hvad kan et Menneske gjøre mig?"],[13,7,"Kommer Eders Veiledere ihu, som have forkyndet Eder det Guds Ord; og naar I betragte Udgangen af deres Vandel, da efterfølger deres Tro.","Kommer Eders Veiledere ihu, som have forkyndet Eder det Guds Ord; og naar I betragte Udgangen af deres Vandel, da efterfølger deres Tro."],[13,8,"Jesus Christus er i Gaar og i Dag den Samme, ja til evig Tid.","Jesus Christus er i Gaar og i Dag den Samme, ja til evig Tid."],[13,9,"Lader Eder ikke omdrive af de mangehaande og fremmede Lærdomme; thi det er godt, at Hjertet styrkes ved Naaden, ikke ved Mad, hvoraf de ingen Nytte have havt, som holdt sig dertil.","Lader Eder ikke omdrive af de mangehaande og fremmede Lærdomme; thi det er godt, at Hjertet styrkes ved Naaden, ikke ved Mad, hvoraf de ingen Nytte have havt, som holdt sig dertil."],[13,10,"Vi have et Alter, af hvilket de ikke have Ret at æde, som tjene ved Tabernaklet.","Vi have et Alter, af hvilket de ikke have Ret at æde, som tjene ved Tabernaklet."],[13,11,"Thi de Dyr, hvis Blod indbæres ved den Ypperstepræst i Helligdommen for Synden, deres Kroppe opbrændes udenfor Leiren.","Thi de Dyr, hvis Blod indbæres ved den Ypperstepræst i Helligdommen for Synden, deres Kroppe opbrændes udenfor Leiren."],[13,12,"Hvorfor Jesus og led udenfor Porten, at han skulde hellige Folket ved sit Blod.","Hvorfor Jesus og led udenfor Porten, at han skulde hellige Folket ved sit Blod."],[13,13,"Derfor lader os gaae ud til ham udenfor Leiren, idet vi bære hans Forsmædelse;","Derfor lader os gaae ud til ham udenfor Leiren, idet vi bære hans Forsmædelse;"],[13,14,"thi vi have ikke her en blivende Stad, men søge efter den tilkommende.","thi vi have ikke her en blivende Stad, men søge efter den tilkommende."],[13,15,"Ved ham lader os da altid frembære Gud Lov-Offer, det er, en Frugt af Læber, som bekjende hans Navn.","Ved ham lader os da altid frembære Gud Lov-Offer, det er, en Frugt af Læber, som bekjende hans Navn."],[13,16,"Men glemmer ikke at gjøre vel og at meddele, thi saadanne Offere behage Gud vel.","Men glemmer ikke at gjøre vel og at meddele, thi saadanne Offere behage Gud vel."],[13,17,"Lyder Eders Veiledere og værer dem hørige; thi de vaage over Eders Sjæle, som de, der skulle gjøre Regnskab, at de kunne gjøre dette med Glæde, og ikke sukkende; thi dette er Eder ikke gavnligt.","Lyder Eders Veiledere og værer dem hørige; thi de vaage over Eders Sjæle, som de, der skulle gjøre Regnskab, at de kunne gjøre dette med Glæde, og ikke sukkende; thi dette er Eder ikke gavnligt."],[13,18,"Beder for os; thi vi fortrøste os til, at vi have en god Samvittighed, som de, der lægge Vind paa at omgaaes vel i alle Ting.","Beder for os; thi vi fortrøste os til, at vi have en god Samvittighed, som de, der lægge Vind paa at omgaaes vel i alle Ting."],[13,19,"Og jeg formaner Eder desmere til at gjøre dette, paa det jeg des snarere kan gives Eder igjen.","Og jeg formaner Eder desmere til at gjøre dette, paa det jeg des snarere kan gives Eder igjen."],[13,20,"Men Fredens Gud, som ved en evig Pagts Blod udførte fra de Døde den store Faarenes Hyrde, vor Herre Jesus,","Men Fredens Gud, som ved en evig Pagts Blod udførte fra de Døde den store Faarenes Hyrde, vor Herre Jesus,"],[13,21,"han befæste Eder i al god Gjerning til at gjøre hans Villie, og han virke i Eder det, som er velbehageligt for ham selv, ved Jesus Christus; ham være Ære i al Evighed; Amen.","han befæste Eder i al god Gjerning til at gjøre hans Villie, og han virke i Eder det, som er velbehageligt for ham selv, ved Jesus Christus; ham være Ære i al Evighed; Amen."],[13,22,"Jeg beder Eder, Brødre! at I fordrage dette Formaningsord; thi korteligen haver jeg skrevet Eder til.","Jeg beder Eder, Brødre! at I fordrage dette Formaningsord; thi korteligen haver jeg skrevet Eder til."],[13,23,"Vider, at Broderen Timotheus er given løs, med hvem jeg vil see Eder, dersom han kommer snart.","Vider, at Broderen Timotheus er given løs, med hvem jeg vil see Eder, dersom han kommer snart."],[13,24,"Hilser alle Eders Veiledere og alle de hellige. De af Italien hilse Eder.","Hilser alle Eders Veiledere og alle de hellige. De af Italien hilse Eder."],[13,25,"Naaden være med Eder alle! Amen.","Naaden være med Eder alle! Amen."]],"epo-londona":[[1,1,"Dio, kiu multafoje kaj multamaniere parolis en la tempo antikva al niaj patroj en la profetoj,","Dio, kiu multafoje kaj multamaniere parolis en la tempo antikva al niaj patroj en la profetoj,"],[1,2,"en tiuj lastaj tagoj parolis al ni en Filo, kiun Li nomis heredanto de ĉio, per kiu ankaŭ Li faris la mondaĝojn,","en tiuj lastaj tagoj parolis al ni en Filo, kiun Li nomis heredanto de ĉio, per kiu ankaŭ Li faris la mondaĝojn,"],[1,3,"kiu, estante la elbrilo de Lia gloro kaj plena bildo de Lia substanco, kaj subtenante ĉion per la vorto de sia potenco, kaj farinte la elpurigon de niaj pekoj, sidiĝis dekstre de la Majesto en altaĵoj;","kiu, estante la elbrilo de Lia gloro kaj plena bildo de Lia substanco, kaj subtenante ĉion per la vorto de sia potenco, kaj farinte la elpurigon de niaj pekoj, sidiĝis dekstre de la Majesto en altaĵoj;"],[1,4,"fariĝinte tiom pli granda ol la anĝeloj, kiom pli bonegan nomon ol ili li heredis.","fariĝinte tiom pli granda ol la anĝeloj, kiom pli bonegan nomon ol ili li heredis."],[1,5,"Ĉar al kiu el la anĝeloj Li iam diris: Vi estas Mia Filo, Hodiaŭ Mi vin naskis? kaj denove: Mi estos al li Patro, Kaj li estos al Mi Filo?","Ĉar al kiu el la anĝeloj Li iam diris: Vi estas Mia Filo, Hodiaŭ Mi vin naskis? kaj denove: Mi estos al li Patro, Kaj li estos al Mi Filo?"],[1,6,"Kaj ankoraŭ, kiam Li enkondukas la unuenaskiton en la mondon, Li diras: Kaj kliniĝu antaŭ li ĉiuj anĝeloj de Dio.","Kaj ankoraŭ, kiam Li enkondukas la unuenaskiton en la mondon, Li diras: Kaj kliniĝu antaŭ li ĉiuj anĝeloj de Dio."],[1,7,"Kaj pri la anĝeloj Li diras: Kiu faras la ventojn Liaj senditoj, Flamantan fajron Liaj servantoj;","Kaj pri la anĝeloj Li diras: Kiu faras la ventojn Liaj senditoj, Flamantan fajron Liaj servantoj;"],[1,8,"sed pri la Filo: Via trono estas Dia trono por ĉiam kaj eterne; La sceptro de via regno estas sceptro de justeco.","sed pri la Filo: Via trono estas Dia trono por ĉiam kaj eterne; La sceptro de via regno estas sceptro de justeco."],[1,9,"Vi amas virton kaj malamas malvirton; Tial Dio, via Dio, oleis vin per oleo de ĝojo pli ol viajn kamaradojn.","Vi amas virton kaj malamas malvirton; Tial Dio, via Dio, oleis vin per oleo de ĝojo pli ol viajn kamaradojn."],[1,10,"Kaj: En antikveco Vi, ho Eternulo, fondis la teron, Kaj la ĉielo estas la faro de Viaj manoj.","Kaj: En antikveco Vi, ho Eternulo, fondis la teron, Kaj la ĉielo estas la faro de Viaj manoj."],[1,11,"Ili pereos, sed Vi restos; Kaj ĉiuj ili eluziĝos kiel vesto,","Ili pereos, sed Vi restos; Kaj ĉiuj ili eluziĝos kiel vesto,"],[1,12,"Kiel veston Vi ilin ŝanĝos, kaj ili ŝanĝiĝos. Sed Vi restas la sama, Kaj Viaj jaroj ne finiĝos.","Kiel veston Vi ilin ŝanĝos, kaj ili ŝanĝiĝos. Sed Vi restas la sama, Kaj Viaj jaroj ne finiĝos."],[1,13,"Sed al kiu el la anĝeloj Li iam diris: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj?","Sed al kiu el la anĝeloj Li iam diris: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj?"],[1,14,"Ĉu ne estas ili ĉiuj spiritoj servantaj, elsendataj, por servi al tiuj, kiuj estas heredontoj de la savo?","Ĉu ne estas ili ĉiuj spiritoj servantaj, elsendataj, por servi al tiuj, kiuj estas heredontoj de la savo?"],[2,1,"Pro tio ni devas pli diligente atenti la aŭditaĵojn, por ke ni de ili ne forflosu.","Pro tio ni devas pli diligente atenti la aŭditaĵojn, por ke ni de ili ne forflosu."],[2,2,"Ĉar se la vorto parolata per anĝeloj montriĝis konstanta, kaj ĉiu dekliniĝo kaj malobeo ricevis justan rekompencon,","Ĉar se la vorto parolata per anĝeloj montriĝis konstanta, kaj ĉiu dekliniĝo kaj malobeo ricevis justan rekompencon,"],[2,3,"kiamaniere ni forsaviĝos, malŝatinte tian gravan savon? kiu, unue ekanoncite per la Sinjoro, estas konfirmita al ni de la aŭdintoj;","kiamaniere ni forsaviĝos, malŝatinte tian gravan savon? kiu, unue ekanoncite per la Sinjoro, estas konfirmita al ni de la aŭdintoj;"],[2,4,"dum Dio ankaŭ kunatestis per signoj kaj mirindaĵoj kaj diversaj potencaĵoj kaj disdonoj de la Sankta Spirito, laŭ Sia volo.","dum Dio ankaŭ kunatestis per signoj kaj mirindaĵoj kaj diversaj potencaĵoj kaj disdonoj de la Sankta Spirito, laŭ Sia volo."],[2,5,"Ĉar ne al anĝeloj Li submetis la estontan mondon, pri kiu ni paroladas.","Ĉar ne al anĝeloj Li submetis la estontan mondon, pri kiu ni paroladas."],[2,6,"Sed iu atestis ie, dirante: Kio estas homo, ke Vi lin memoras? Kio estas homido, ke Vi pensas pri li?","Sed iu atestis ie, dirante: Kio estas homo, ke Vi lin memoras? Kio estas homido, ke Vi pensas pri li?"],[2,7,"Vi malaltigis lin malmulte antaŭ la anĝeloj, Per honoro kaj beleco Vi lin kronis. Vi faris lin reganto super la faritaĵoj de Viaj manoj;","Vi malaltigis lin malmulte antaŭ la anĝeloj, Per honoro kaj beleco Vi lin kronis. Vi faris lin reganto super la faritaĵoj de Viaj manoj;"],[2,8,"Ĉion Vi metis sub liajn piedojn. Ĉar, metante ĉion sub lin, Li nenion lasis ne submetita. Sed nun ni ankoraŭ ne vidas ĉion submetita sub lin.","Ĉion Vi metis sub liajn piedojn. Ĉar, metante ĉion sub lin, Li nenion lasis ne submetita. Sed nun ni ankoraŭ ne vidas ĉion submetita sub lin."],[2,9,"Sed la malmulte sub la anĝeloj malaltigitan Jesuon ni vidas, pro la sufero de morto, kronita per honoro kaj beleco, por ke per la favoro de Dio li gustumu morton por ĉiu.","Sed la malmulte sub la anĝeloj malaltigitan Jesuon ni vidas, pro la sufero de morto, kronita per honoro kaj beleco, por ke per la favoro de Dio li gustumu morton por ĉiu."],[2,10,"Ĉar konvenis al Li, por kiu ĉio estas, kaj de kiu ĉio estas, alkondukanta multajn filojn al gloro, perfektigi per suferado la estron de ilia savo.","Ĉar konvenis al Li, por kiu ĉio estas, kaj de kiu ĉio estas, alkondukanta multajn filojn al gloro, perfektigi per suferado la estron de ilia savo."],[2,11,"Ĉar la sanktiganto kaj la sanktigatoj estas ĉiuj el unu; pro tiu kaŭzo li ne hontas nomi ilin fratoj,","Ĉar la sanktiganto kaj la sanktigatoj estas ĉiuj el unu; pro tiu kaŭzo li ne hontas nomi ilin fratoj,"],[2,12,"dirante: Mi predikos Vian nomon al miaj fratoj, En la mezo de popola kunveno mi Vin gloros.","dirante: Mi predikos Vian nomon al miaj fratoj, En la mezo de popola kunveno mi Vin gloros."],[2,13,"Kaj ankaŭ: Mi fidos Lin. Kaj ankaŭ: Jen mi kaj la infanoj, kiujn Dio donis al mi.","Kaj ankaŭ: Mi fidos Lin. Kaj ankaŭ: Jen mi kaj la infanoj, kiujn Dio donis al mi."],[2,14,"Ĉar do la infanoj partoprenas en sango kaj karno, li ankaŭ mem egale partoprenis en ili, por ke per morto li neniigu tiun, kiu havis la potencon de morto, tio estas la diablo,","Ĉar do la infanoj partoprenas en sango kaj karno, li ankaŭ mem egale partoprenis en ili, por ke per morto li neniigu tiun, kiu havis la potencon de morto, tio estas la diablo,"],[2,15,"kaj liberigu tiujn, kiuj per timo de morto dum la tuta vivo estis subigitaj al sklaveco.","kaj liberigu tiujn, kiuj per timo de morto dum la tuta vivo estis subigitaj al sklaveco."],[2,16,"Ĉar vere li ektenas ne anĝelojn, sed la idaron de Abraham li ektenas.","Ĉar vere li ektenas ne anĝelojn, sed la idaron de Abraham li ektenas."],[2,17,"Tial li devis en ĉio similiĝi al siaj fratoj, por ke li fariĝu kompatema kaj fidela ĉefpastro en la aferoj de Dio, por fari repacigon por la pekoj de la popolo.","Tial li devis en ĉio similiĝi al siaj fratoj, por ke li fariĝu kompatema kaj fidela ĉefpastro en la aferoj de Dio, por fari repacigon por la pekoj de la popolo."],[2,18,"Ĉar per tio, ke li mem, tentate, suferis, li povas helpi la tentatojn.","Ĉar per tio, ke li mem, tentate, suferis, li povas helpi la tentatojn."],[3,1,"Tial, fratoj sanktaj, partoprenantaj en ĉiela voko, pripensu la Apostolon kaj Ĉefpastron de nia konfeso, Jesuon,","Tial, fratoj sanktaj, partoprenantaj en ĉiela voko, pripensu la Apostolon kaj Ĉefpastron de nia konfeso, Jesuon,"],[3,2,"kiu estis fidela al Tiu, kiu nomis lin kiel ankaŭ Moseo en Lia domo.","kiu estis fidela al Tiu, kiu nomis lin kiel ankaŭ Moseo en Lia domo."],[3,3,"Ĉar ĉi tiu estas rigardita kiel inda je tiom pli granda gloro ol Moseo, kiom pli grandan honoron, ol la domo, havas ĝia stariginto.","Ĉar ĉi tiu estas rigardita kiel inda je tiom pli granda gloro ol Moseo, kiom pli grandan honoron, ol la domo, havas ĝia stariginto."],[3,4,"Ĉar ĉiu domo estas starigita de iu; sed la stariginto de ĉio estas Dio.","Ĉar ĉiu domo estas starigita de iu; sed la stariginto de ĉio estas Dio."],[3,5,"Kaj Moseo ja estis fidela en Lia tuta domo, kiel servanto, por atestaĵo pri tio, kio estis parolota;","Kaj Moseo ja estis fidela en Lia tuta domo, kiel servanto, por atestaĵo pri tio, kio estis parolota;"],[3,6,"sed Kristo, kiel filo super Lia domo; kies domo ni estas, se ni tenos nian kuraĝon kaj la ĝojadon de nia espero firmaj ĝis la fino.","sed Kristo, kiel filo super Lia domo; kies domo ni estas, se ni tenos nian kuraĝon kaj la ĝojadon de nia espero firmaj ĝis la fino."],[3,7,"Tial, kiel diras la Sankta Spirito: Hodiaŭ, se vi aŭskultas Lian voĉon,","Tial, kiel diras la Sankta Spirito: Hodiaŭ, se vi aŭskultas Lian voĉon,"],[3,8,"Ne obstinigu vian koron, kiel en la indignigo, Kiel en la tago de la tento en la dezerto,","Ne obstinigu vian koron, kiel en la indignigo, Kiel en la tago de la tento en la dezerto,"],[3,9,"Kiam viaj patroj Min incitis, Esploris kaj vidis Miajn farojn kvardek jarojn.","Kiam viaj patroj Min incitis, Esploris kaj vidis Miajn farojn kvardek jarojn."],[3,10,"Pro tio Mi indignis kontraŭ tiu generacio, Kaj Mi diris: Ili ĉiam estas kun koro malĝusta, Kaj ili ne volas koni Miajn vojojn;","Pro tio Mi indignis kontraŭ tiu generacio, Kaj Mi diris: Ili ĉiam estas kun koro malĝusta, Kaj ili ne volas koni Miajn vojojn;"],[3,11,"Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon.","Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon."],[3,12,"Gardu vin, fratoj, ke ne estu en iu el vi koro malbona de nekredemo, en defalo de la vivanta Dio;","Gardu vin, fratoj, ke ne estu en iu el vi koro malbona de nekredemo, en defalo de la vivanta Dio;"],[3,13,"sed konsilu unu la alian ĉiutage, dum estas nomate hodiaŭ, por ke neniu el vi estu obstinigita per la trompeco de peko;","sed konsilu unu la alian ĉiutage, dum estas nomate hodiaŭ, por ke neniu el vi estu obstinigita per la trompeco de peko;"],[3,14,"ĉar ni fariĝis partoprenantoj en Kristo, se la komencon de nia certiĝo ni tenos firma ĝis la fino;","ĉar ni fariĝis partoprenantoj en Kristo, se la komencon de nia certiĝo ni tenos firma ĝis la fino;"],[3,15,"dum estas dirite: Hodiaŭ, se vi aŭskultas Lian voĉon, Ne obstinigu vian koron, kiel en la indignigo.","dum estas dirite: Hodiaŭ, se vi aŭskultas Lian voĉon, Ne obstinigu vian koron, kiel en la indignigo."],[3,16,"Ĉar kiuj, aŭskultinte, indignigis? ĉu ne ĉiuj elirintoj el Egiptujo per Moseo?","Ĉar kiuj, aŭskultinte, indignigis? ĉu ne ĉiuj elirintoj el Egiptujo per Moseo?"],[3,17,"Kaj kontraŭ kiuj Li indignis kvardek jarojn? ĉu ne kontraŭ la pekintoj, kies korpoj falis en la dezerto?","Kaj kontraŭ kiuj Li indignis kvardek jarojn? ĉu ne kontraŭ la pekintoj, kies korpoj falis en la dezerto?"],[3,18,"Kaj al kiuj Li ĵuris, ke ili ne venos en Lian ripozejon, krom al la neobeantoj?","Kaj al kiuj Li ĵuris, ke ili ne venos en Lian ripozejon, krom al la neobeantoj?"],[3,19,"Kaj ni vidas, ke ili pro nekredemo ne povis enveni.","Kaj ni vidas, ke ili pro nekredemo ne povis enveni."],[4,1,"Ni do timu, ke, kiam al ni restas promeso veni en Lian ripozejon, iu el vi eble ŝajne malatingos ĝin.","Ni do timu, ke, kiam al ni restas promeso veni en Lian ripozejon, iu el vi eble ŝajne malatingos ĝin."],[4,2,"Ĉar al ni ankaŭ estas evangelio anoncita tiel same, kiel al ili; sed al ili la aŭdita parolo ne utilis, ne miksite kun fido ĉe la aŭdantoj.","Ĉar al ni ankaŭ estas evangelio anoncita tiel same, kiel al ili; sed al ili la aŭdita parolo ne utilis, ne miksite kun fido ĉe la aŭdantoj."],[4,3,"Ĉar ni ekkredintoj venas en la ripozejon, kiel Li diris: Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon; kvankam la faritaĵoj estis finitaj jam de post la fondo de la mondo.","Ĉar ni ekkredintoj venas en la ripozejon, kiel Li diris: Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon; kvankam la faritaĵoj estis finitaj jam de post la fondo de la mondo."],[4,4,"Ĉar Li diris ie pri la sepa tago jene: Kaj Dio ripozis en la sepa tago de Sia tuta laboro;","Ĉar Li diris ie pri la sepa tago jene: Kaj Dio ripozis en la sepa tago de Sia tuta laboro;"],[4,5,"kaj ankaŭ jene: Ili ne venos en Mian ripozejon.","kaj ankaŭ jene: Ili ne venos en Mian ripozejon."],[4,6,"Ĉar restas do por iuj veni en ĝin, kaj tiuj, al kiuj la evangelio unue estis predikita, ne envenis pro malobeo,","Ĉar restas do por iuj veni en ĝin, kaj tiuj, al kiuj la evangelio unue estis predikita, ne envenis pro malobeo,"],[4,7,"denove Li difinis iun tagon, dirante en David: Hodiaŭ, post tiom da tempo; kiel estas dirite: Hodiaŭ, se vi aŭskultas Lian voĉon, Ne obstinigu vian koron.","denove Li difinis iun tagon, dirante en David: Hodiaŭ, post tiom da tempo; kiel estas dirite: Hodiaŭ, se vi aŭskultas Lian voĉon, Ne obstinigu vian koron."],[4,8,"Ĉar se Josuo al ili estus doninta ripozon, Li ne parolus poste pri alia tago.","Ĉar se Josuo al ili estus doninta ripozon, Li ne parolus poste pri alia tago."],[4,9,"Tial restas sabata ripozo por la popolo de Dio.","Tial restas sabata ripozo por la popolo de Dio."],[4,10,"Ĉar tiu, kiu venis en sian ripozejon, ankaŭ mem ripozas de siaj faroj, kiel Dio de Siaj.","Ĉar tiu, kiu venis en sian ripozejon, ankaŭ mem ripozas de siaj faroj, kiel Dio de Siaj."],[4,11,"Ni klopodu do veni en tiun ripozejon, por ke neniu falu laŭ la sama ekzemplo de malobeo.","Ni klopodu do veni en tiun ripozejon, por ke neniu falu laŭ la sama ekzemplo de malobeo."],[4,12,"Ĉar la vorto de Dio estas viva kaj energia, kaj pli akra ol ĉia glavo dutranĉa, kaj penetranta ĝis divido de la animo kaj spirito, kaj de artikoj kaj medolo, kaj kritikanta la pensojn kaj celojn de la koro.","Ĉar la vorto de Dio estas viva kaj energia, kaj pli akra ol ĉia glavo dutranĉa, kaj penetranta ĝis divido de la animo kaj spirito, kaj de artikoj kaj medolo, kaj kritikanta la pensojn kaj celojn de la koro."],[4,13,"Kaj ne ekzistas kreitaĵo kaŝita antaŭ Lia vidado; sed ĉio estas nuda kaj evidenta al la okuloj de Tiu, al kiu nia afero rilatas.","Kaj ne ekzistas kreitaĵo kaŝita antaŭ Lia vidado; sed ĉio estas nuda kaj evidenta al la okuloj de Tiu, al kiu nia afero rilatas."],[4,14,"Havante do ĉefpastron grandan, trapasintan la ĉielon, Jesuon, la Filon de Dio, ni tenu firme nian konfeson.","Havante do ĉefpastron grandan, trapasintan la ĉielon, Jesuon, la Filon de Dio, ni tenu firme nian konfeson."],[4,15,"Ĉar ni havas ĉefpastron ne tian, kiu ne povus simpatii kun niaj malfortaĵoj, sed tentitan en ĉio tiel same, tamen sen peko.","Ĉar ni havas ĉefpastron ne tian, kiu ne povus simpatii kun niaj malfortaĵoj, sed tentitan en ĉio tiel same, tamen sen peko."],[4,16,"Ni do alvenu kun kuraĝo al la trono de graco, por ke ni ricevu kompaton kaj trovu gracon por ĝustatempa helpo.","Ni do alvenu kun kuraĝo al la trono de graco, por ke ni ricevu kompaton kaj trovu gracon por ĝustatempa helpo."],[5,1,"Ĉar ĉiu ĉefpastro, prenata el inter homoj, pro homoj estas difinita por aferoj rilatantaj al Dio, por ke li oferu kaj donacojn kaj oferojn pro pekoj;","Ĉar ĉiu ĉefpastro, prenata el inter homoj, pro homoj estas difinita por aferoj rilatantaj al Dio, por ke li oferu kaj donacojn kaj oferojn pro pekoj;"],[5,2,"povante indulgi tiujn, kiuj estas malkleraj kaj erarantaj, tial, ke li mem estas ĉirkaŭata de malforteco;","povante indulgi tiujn, kiuj estas malkleraj kaj erarantaj, tial, ke li mem estas ĉirkaŭata de malforteco;"],[5,3,"kaj pro tio li devas, kiel por la popolo, tiel ankaŭ por si mem, oferi pro pekoj.","kaj pro tio li devas, kiel por la popolo, tiel ankaŭ por si mem, oferi pro pekoj."],[5,4,"Kaj neniu alprenas al si tiun honoron krom la vokato de Dio, tiel same, kiel Aaron.","Kaj neniu alprenas al si tiun honoron krom la vokato de Dio, tiel same, kiel Aaron."],[5,5,"Tiel ankaŭ Kristo sin mem ne honoris, por fariĝi ĉefpastro, sed lin honoris Tiu, kiu diris al li: Vi estas Mia Filo, Hodiaŭ Mi vin naskis;","Tiel ankaŭ Kristo sin mem ne honoris, por fariĝi ĉefpastro, sed lin honoris Tiu, kiu diris al li: Vi estas Mia Filo, Hodiaŭ Mi vin naskis;"],[5,6,"kiel ankaŭ aliloke Li diris: Vi estas pastro por ĉiam, Laŭ la maniero de Melkicedek.","kiel ankaŭ aliloke Li diris: Vi estas pastro por ĉiam, Laŭ la maniero de Melkicedek."],[5,7,"En siaj karnaj tagoj, preĝojn kaj petegojn oferinte, kun forta kriado kaj larmoj, al Tiu, kiu povis lin savi el morto, kaj aŭdite pro sia pia timo,","En siaj karnaj tagoj, preĝojn kaj petegojn oferinte, kun forta kriado kaj larmoj, al Tiu, kiu povis lin savi el morto, kaj aŭdite pro sia pia timo,"],[5,8,"tiu, kvankam li estis Filo, tamen lernis obeon per tio, kion li suferis;","tiu, kvankam li estis Filo, tamen lernis obeon per tio, kion li suferis;"],[5,9,"kaj perfektigite, li fariĝis la fonto de eterna savo al ĉiuj al li obeantaj;","kaj perfektigite, li fariĝis la fonto de eterna savo al ĉiuj al li obeantaj;"],[5,10,"nomite de Dio ĉefpastro laŭ la maniero de Melkicedek.","nomite de Dio ĉefpastro laŭ la maniero de Melkicedek."],[5,11,"Pri tiu ni havas dirotaĵojn multajn, kaj malfacile klarigeblajn tial, ke vi surdiĝis en aŭdado.","Pri tiu ni havas dirotaĵojn multajn, kaj malfacile klarigeblajn tial, ke vi surdiĝis en aŭdado."],[5,12,"Ĉar kvankam vi jam devus esti instruistoj, vi ankoraŭ bezonas, ke oni instruu al vi, kiaj estas la komencaj elementoj de la orakoloj de Dio, kaj vi fariĝis bezonantoj de lakto kaj ne de solida nutraĵo.","Ĉar kvankam vi jam devus esti instruistoj, vi ankoraŭ bezonas, ke oni instruu al vi, kiaj estas la komencaj elementoj de la orakoloj de Dio, kaj vi fariĝis bezonantoj de lakto kaj ne de solida nutraĵo."],[5,13,"Ĉar ĉiu, kiu nutriĝas per lakto, estas nesperta rilate la vorton de justeco; ĉar li estas infaneto.","Ĉar ĉiu, kiu nutriĝas per lakto, estas nesperta rilate la vorton de justeco; ĉar li estas infaneto."],[5,14,"Sed solida nutraĵo estas por la plenaĝuloj, kiuj per uzado havas la sentojn ekzercitaj, por distingi inter bono kaj malbono.","Sed solida nutraĵo estas por la plenaĝuloj, kiuj per uzado havas la sentojn ekzercitaj, por distingi inter bono kaj malbono."],[6,1,"Tial, ĉesigante la diskutadon pri la elementoj de Kristo, ni iru antaŭen al perfektiĝo, ne metante denove fundamenton de pento el malvivaj faroj kaj de fido al Dio,","Tial, ĉesigante la diskutadon pri la elementoj de Kristo, ni iru antaŭen al perfektiĝo, ne metante denove fundamenton de pento el malvivaj faroj kaj de fido al Dio,"],[6,2,"de la dogmaro pri baptoj, surmetado de manoj, de revivigo de mortintoj, de eterna juĝo.","de la dogmaro pri baptoj, surmetado de manoj, de revivigo de mortintoj, de eterna juĝo."],[6,3,"Kaj tion ni faros, se Dio permesos.","Kaj tion ni faros, se Dio permesos."],[6,4,"Ĉar ĉe tiuj, kiuj unufoje estas allumitaj kaj gustumis la ĉielan donon kaj fariĝis partoprenantoj en la Sankta Spirito,","Ĉar ĉe tiuj, kiuj unufoje estas allumitaj kaj gustumis la ĉielan donon kaj fariĝis partoprenantoj en la Sankta Spirito,"],[6,5,"kaj gustumis la bonan vorton de Dio kaj la potencojn de la estonta mondo,","kaj gustumis la bonan vorton de Dio kaj la potencojn de la estonta mondo,"],[6,6,"kaj defalis, ne estas eble renovigi ilin ankoraŭ al pento, dum ili rekrucumas al si la Filon de Dio kaj elmetas lin al publika malhonoro.","kaj defalis, ne estas eble renovigi ilin ankoraŭ al pento, dum ili rekrucumas al si la Filon de Dio kaj elmetas lin al publika malhonoro."],[6,7,"Ĉar la tero, kiu entrinkis la pluvon, sur ĝin ofte venantan, kaj produktas kreskaĵojn, taŭgajn por tiuj, pro kiuj ĝi ankaŭ estas kultivata, ricevas benon de Dio;","Ĉar la tero, kiu entrinkis la pluvon, sur ĝin ofte venantan, kaj produktas kreskaĵojn, taŭgajn por tiuj, pro kiuj ĝi ankaŭ estas kultivata, ricevas benon de Dio;"],[6,8,"sed se ĝi donas dornojn kaj kardojn, ĝi estas malaprobata kaj proksima al malbeno; ĝia fino estas en brulado.","sed se ĝi donas dornojn kaj kardojn, ĝi estas malaprobata kaj proksima al malbeno; ĝia fino estas en brulado."],[6,9,"Sed ni certigas al ni aferojn pli bonajn pri vi, amatoj, kaj aferojn, kiuj akompanas savon, kvankam ni tiel parolas;","Sed ni certigas al ni aferojn pli bonajn pri vi, amatoj, kaj aferojn, kiuj akompanas savon, kvankam ni tiel parolas;"],[6,10,"ĉar Dio ne estas maljusta, por forgesi vian laboron kaj la amon, kiun vi montris al Lia nomo, servinte al la sanktuloj kaj ankoraŭ servante.","ĉar Dio ne estas maljusta, por forgesi vian laboron kaj la amon, kiun vi montris al Lia nomo, servinte al la sanktuloj kaj ankoraŭ servante."],[6,11,"Sed ni deziras, ke ĉiu el vi montru tian saman diligentecon por la plenumo de la espero ĝis la fino;","Sed ni deziras, ke ĉiu el vi montru tian saman diligentecon por la plenumo de la espero ĝis la fino;"],[6,12,"por ke vi fariĝu ne maldiligentaj, sed imitantoj de tiuj, kiuj per fido kaj pacienco heredas la promesojn.","por ke vi fariĝu ne maldiligentaj, sed imitantoj de tiuj, kiuj per fido kaj pacienco heredas la promesojn."],[6,13,"Ĉar kiam Dio promesis al Abraham, Li ĵuris per Si mem (ĉar Li ne povis ĵuri per iu pli granda),","Ĉar kiam Dio promesis al Abraham, Li ĵuris per Si mem (ĉar Li ne povis ĵuri per iu pli granda),"],[6,14,"dirante: Certe benante Mi benos vin, kaj multigante Mi multigos vin.","dirante: Certe benante Mi benos vin, kaj multigante Mi multigos vin."],[6,15,"Kaj tiel, atendinte kun pacienco, li atingis la promeson.","Kaj tiel, atendinte kun pacienco, li atingis la promeson."],[6,16,"Ĉar homoj ĵuras per la pli granda, kaj ĉe ili la ĵuro por certigo estas fino de ĉia disputado.","Ĉar homoj ĵuras per la pli granda, kaj ĉe ili la ĵuro por certigo estas fino de ĉia disputado."],[6,17,"Kaj Dio, volante montri pli abunde al la heredantoj de la promeso la neŝanĝeblecon de Sia intenco, intermetis ĵuron,","Kaj Dio, volante montri pli abunde al la heredantoj de la promeso la neŝanĝeblecon de Sia intenco, intermetis ĵuron,"],[6,18,"por ke per du neŝanĝeblaj aferoj, en kiuj ne eble estas por Dio mensogi, fortan konsolon havu ni, kiuj rifuĝis, por akiri la esperon antaŭ ni metitan,","por ke per du neŝanĝeblaj aferoj, en kiuj ne eble estas por Dio mensogi, fortan konsolon havu ni, kiuj rifuĝis, por akiri la esperon antaŭ ni metitan,"],[6,19,"kiun ni havas kiel ankron de la animo, firman kaj konstantan, enirantan internen de la kurteno;","kiun ni havas kiel ankron de la animo, firman kaj konstantan, enirantan internen de la kurteno;"],[6,20,"kien eniris Jesuo, la antaŭulo por ni, fariĝinte ĉefpastro por ĉiam laŭ la maniero de Melkicedek.","kien eniris Jesuo, la antaŭulo por ni, fariĝinte ĉefpastro por ĉiam laŭ la maniero de Melkicedek."],[7,1,"Ĉar tiu Melkicedek, reĝo de Salem, pastro de Dio la Plejalta, kiu renkontis Abrahamon revenantan de la mortigado de la reĝoj, kaj lin benis,","Ĉar tiu Melkicedek, reĝo de Salem, pastro de Dio la Plejalta, kiu renkontis Abrahamon revenantan de la mortigado de la reĝoj, kaj lin benis,"],[7,2,"kaj al kiu ankaŭ Abraham donis dekonon el ĉio (unue laŭ interpreto reĝo de justeco, kaj poste reĝo de Salem, tio estas reĝo de paco;","kaj al kiu ankaŭ Abraham donis dekonon el ĉio (unue laŭ interpreto reĝo de justeco, kaj poste reĝo de Salem, tio estas reĝo de paco;"],[7,3,"senpatra, senpatrina, sengenealogia, havanta nek komencon de tagoj, nek finon de vivo, sed similigita al la Filo de Dio), restas pastro por ĉiam.","senpatra, senpatrina, sengenealogia, havanta nek komencon de tagoj, nek finon de vivo, sed similigita al la Filo de Dio), restas pastro por ĉiam."],[7,4,"Nun pripensu, kiel granda estis ĉi tiu, al kiu la patriarko Abraham donis dekonon el la akiraĵoj.","Nun pripensu, kiel granda estis ĉi tiu, al kiu la patriarko Abraham donis dekonon el la akiraĵoj."],[7,5,"Kaj efektive el la filoj de Levi tiuj, kiuj ricevas la pastran oficon, havas ordonon imposti laŭleĝe podekone la popolon, tio estas, siajn fratojn, kvankam elirintajn el la lumboj de Abraham;","Kaj efektive el la filoj de Levi tiuj, kiuj ricevas la pastran oficon, havas ordonon imposti laŭleĝe podekone la popolon, tio estas, siajn fratojn, kvankam elirintajn el la lumboj de Abraham;"],[7,6,"sed tiu, kies genealogio ne estas el ili, ricevis de Abraham dekonaĵon, kaj benis tiun, kiu havis la promesojn.","sed tiu, kies genealogio ne estas el ili, ricevis de Abraham dekonaĵon, kaj benis tiun, kiu havis la promesojn."],[7,7,"Sed ekster ĉia kontraŭparolo, la malpli granda ricevas benon de la pli granda.","Sed ekster ĉia kontraŭparolo, la malpli granda ricevas benon de la pli granda."],[7,8,"Kaj ĉi tie homoj, kiuj mortas, ricevas dekonaĵojn, sed tie unu, pri kiu estas atestate, ke li vivas.","Kaj ĉi tie homoj, kiuj mortas, ricevas dekonaĵojn, sed tie unu, pri kiu estas atestate, ke li vivas."],[7,9,"Kaj, por tiel diri, per Abraham ankaŭ Levi, la ricevanto de dekonaĵoj, donis dekonaĵon;","Kaj, por tiel diri, per Abraham ankaŭ Levi, la ricevanto de dekonaĵoj, donis dekonaĵon;"],[7,10,"ĉar li estis ankoraŭ en la lumboj de la patro, kiam Melkicedek lin renkontis.","ĉar li estis ankoraŭ en la lumboj de la patro, kiam Melkicedek lin renkontis."],[7,11,"Tial, se ekzistis perfekteco per la Levida pastreco (ĉar sub ĝi la popolo ricevis la leĝon), kia plua bezono estis, ke leviĝu alia pastro laŭ la maniero de Melkicedek, kaj ne estu nomata laŭ la maniero de Aaron?","Tial, se ekzistis perfekteco per la Levida pastreco (ĉar sub ĝi la popolo ricevis la leĝon), kia plua bezono estis, ke leviĝu alia pastro laŭ la maniero de Melkicedek, kaj ne estu nomata laŭ la maniero de Aaron?"],[7,12,"Ĉar kiam la pastraro ŝanĝiĝas, necese ankaŭ fariĝas ŝanĝo de leĝo.","Ĉar kiam la pastraro ŝanĝiĝas, necese ankaŭ fariĝas ŝanĝo de leĝo."],[7,13,"Ĉar tiu, pri kiu tio estas dirita, estas ano de alia tribo, el kiu neniu servis ĉe la altaro.","Ĉar tiu, pri kiu tio estas dirita, estas ano de alia tribo, el kiu neniu servis ĉe la altaro."],[7,14,"Ĉar evidente estas, ke nia Sinjoro devenis de Jehuda, pri kiu tribo Moseo diris nenion rilate pastrecon.","Ĉar evidente estas, ke nia Sinjoro devenis de Jehuda, pri kiu tribo Moseo diris nenion rilate pastrecon."],[7,15,"Kaj tio eĉ pli evidenta estas, se laŭ simileco de Melkicedek leviĝas pastro alia,","Kaj tio eĉ pli evidenta estas, se laŭ simileco de Melkicedek leviĝas pastro alia,"],[7,16,"kiu estas farita ne laŭ la leĝo de ordono karna, sed laŭ la potenco de vivo nedetruebla;","kiu estas farita ne laŭ la leĝo de ordono karna, sed laŭ la potenco de vivo nedetruebla;"],[7,17,"ĉar li havas la ateston: Vi estas pastro por ĉiam Laŭ la maniero de Melkicedek.","ĉar li havas la ateston: Vi estas pastro por ĉiam Laŭ la maniero de Melkicedek."],[7,18,"Ĉar okazas vere nuligado de antaŭiranta ordono, pro ĝia malforteco kaj senutileco","Ĉar okazas vere nuligado de antaŭiranta ordono, pro ĝia malforteco kaj senutileco"],[7,19,"(ĉar la leĝo nenion perfektigis); kaj okazas la enkonduko de pli bona espero, per kiu ni alproksimiĝas al Dio.","(ĉar la leĝo nenion perfektigis); kaj okazas la enkonduko de pli bona espero, per kiu ni alproksimiĝas al Dio."],[7,20,"Kaj pro tio, ke ne mankas ĵurado","Kaj pro tio, ke ne mankas ĵurado"],[7,21,"(ĉar ili sen ĵurado estas faritaj pastroj, sed ĉi tiu kun ĵuro laŭ Tiu, kiu diris pri li: La Eternulo ĵuris, kaj ne pentos: Vi estas pastro por ĉiam);","(ĉar ili sen ĵurado estas faritaj pastroj, sed ĉi tiu kun ĵuro laŭ Tiu, kiu diris pri li: La Eternulo ĵuris, kaj ne pentos: Vi estas pastro por ĉiam);"],[7,22,"Jesuo fariĝis garantiulo de des pli bona interligo.","Jesuo fariĝis garantiulo de des pli bona interligo."],[7,23,"Kaj ili ja fariĝis pastroj multenombraj, ĉar pro morto estas malpermesate al ili daŭri;","Kaj ili ja fariĝis pastroj multenombraj, ĉar pro morto estas malpermesate al ili daŭri;"],[7,24,"sed ĉi tiu, pro sia eterna daŭrado, havas sian pastrecon neŝanĝebla.","sed ĉi tiu, pro sia eterna daŭrado, havas sian pastrecon neŝanĝebla."],[7,25,"Tial ankaŭ li povas savi ĝis la ekstremaĵo tiujn, kiuj alproksimiĝas per li al Dio, ĉar li ĉiam vivas, por propeti pro ili.","Tial ankaŭ li povas savi ĝis la ekstremaĵo tiujn, kiuj alproksimiĝas per li al Dio, ĉar li ĉiam vivas, por propeti pro ili."],[7,26,"Ĉar por ni konvenis tia ĉefpastro, sankta, senpeka, senmakula, apartigita for de pekuloj, kaj farita pli alta ol la ĉielo;","Ĉar por ni konvenis tia ĉefpastro, sankta, senpeka, senmakula, apartigita for de pekuloj, kaj farita pli alta ol la ĉielo;"],[7,27,"li ne havas ĉiutagan necesecon, kiel tiuj ĉefpastroj, oferi oferojn, unue pro la propraj pekoj, poste pro la pekoj de la popolo; ĉar tion li faris unufoje por ĉiam, oferante sin mem.","li ne havas ĉiutagan necesecon, kiel tiuj ĉefpastroj, oferi oferojn, unue pro la propraj pekoj, poste pro la pekoj de la popolo; ĉar tion li faris unufoje por ĉiam, oferante sin mem."],[7,28,"Ĉar la leĝo starigas kiel ĉefpastrojn homojn, kiuj havas malfortecon; sed la vorto de la ĵuro, kiu estas post la leĝo, nomas Filon, perfektigitan por ĉiam.","Ĉar la leĝo starigas kiel ĉefpastrojn homojn, kiuj havas malfortecon; sed la vorto de la ĵuro, kiu estas post la leĝo, nomas Filon, perfektigitan por ĉiam."],[8,1,"Jen do la resumo rilate la diritaĵojn: Ni havas tian ĉefpastron, kiu sidiĝis dekstre de la trono de la Majesto en la ĉielo,","Jen do la resumo rilate la diritaĵojn: Ni havas tian ĉefpastron, kiu sidiĝis dekstre de la trono de la Majesto en la ĉielo,"],[8,2,"servanto de la sanktejo, kaj de la vera tabernaklo, kiun starigis ne homo, sed la Sinjoro.","servanto de la sanktejo, kaj de la vera tabernaklo, kiun starigis ne homo, sed la Sinjoro."],[8,3,"Ĉar ĉiu ĉefpastro estas enoficigita por oferi donacojn kaj oferojn; kaj tial estas necese, ke ankaŭ ĉi tiu havu ion por oferi.","Ĉar ĉiu ĉefpastro estas enoficigita por oferi donacojn kaj oferojn; kaj tial estas necese, ke ankaŭ ĉi tiu havu ion por oferi."],[8,4,"Sed se li estus sur la tero, li tute ne estus pastro, tial, ke jam ekzistas oferantoj de donacoj laŭ la leĝo;","Sed se li estus sur la tero, li tute ne estus pastro, tial, ke jam ekzistas oferantoj de donacoj laŭ la leĝo;"],[8,5,"kiuj servas al la ekzemplo kaj ombro de ĉielaj aferoj, kiel Moseo estis admonita, faronte la tabernaklon; ĉar: Zorgu, Li diris, ke vi faru ĉion laŭ la modelo, kiu estis montrita al vi sur la monto.","kiuj servas al la ekzemplo kaj ombro de ĉielaj aferoj, kiel Moseo estis admonita, faronte la tabernaklon; ĉar: Zorgu, Li diris, ke vi faru ĉion laŭ la modelo, kiu estis montrita al vi sur la monto."],[8,6,"Sed nun li ricevis servadon des pli bonan, ju pli bona estas la interligo, kies interulo li fariĝis kaj kiu sur pli bonaj promesoj estas dekretita.","Sed nun li ricevis servadon des pli bonan, ju pli bona estas la interligo, kies interulo li fariĝis kaj kiu sur pli bonaj promesoj estas dekretita."],[8,7,"Ĉar se tiu unua interligo estus sendifekta, tiam ne estus serĉita loko por dua.","Ĉar se tiu unua interligo estus sendifekta, tiam ne estus serĉita loko por dua."],[8,8,"Ĉar riproĉante ilin, Li diris: Jen venos la tempo, diras la Eternulo, Kiam Mi faros kun la domo de Izrael kaj la domo de Jehuda interligon novan:","Ĉar riproĉante ilin, Li diris: Jen venos la tempo, diras la Eternulo, Kiam Mi faros kun la domo de Izrael kaj la domo de Jehuda interligon novan:"],[8,9,"Ne tian, kiel la interligo, kiun Mi faris kun iliaj patroj En la tago, kiam Mi prenis ilian manon, por elkonduki ilin el la lando Egipta, Ĉar ili ne restis en Mia interligo, Kaj Mi malatentis ilin, diris la Eternulo.","Ne tian, kiel la interligo, kiun Mi faris kun iliaj patroj En la tago, kiam Mi prenis ilian manon, por elkonduki ilin el la lando Egipta, Ĉar ili ne restis en Mia interligo, Kaj Mi malatentis ilin, diris la Eternulo."],[8,10,"Sed jen estas la interligo, kiun Mi faros kun la domo de Izrael Post tiu tempo, diras la Eternulo: Mi metos Miajn leĝojn en ilian internon, Kaj sur ilia koro Mi ilin skribos, Kaj Mi estos ilia Dio, Kaj ili estos Mia popolo.","Sed jen estas la interligo, kiun Mi faros kun la domo de Izrael Post tiu tempo, diras la Eternulo: Mi metos Miajn leĝojn en ilian internon, Kaj sur ilia koro Mi ilin skribos, Kaj Mi estos ilia Dio, Kaj ili estos Mia popolo."],[8,11,"Kaj ne plu instruos ĉiu sian proksimulon, Kaj ĉiu sian fraton, dirante: Ekkonu la Eternulon; Ĉar ĉiuj Min konos, De iliaj malgranduloj ĝis iliaj granduloj;","Kaj ne plu instruos ĉiu sian proksimulon, Kaj ĉiu sian fraton, dirante: Ekkonu la Eternulon; Ĉar ĉiuj Min konos, De iliaj malgranduloj ĝis iliaj granduloj;"],[8,12,"Ĉar Mi pardonos iliajn kulpojn, Kaj iliajn pekojn kaj malbonaĵojn Mi ne plu rememoros.","Ĉar Mi pardonos iliajn kulpojn, Kaj iliajn pekojn kaj malbonaĵojn Mi ne plu rememoros."],[8,13,"Dirante: Novan interligon — Li malnovigis la unuan. Kaj tio, kio kadukiĝas kaj malnoviĝas estas proksima al malapero.","Dirante: Novan interligon — Li malnovigis la unuan. Kaj tio, kio kadukiĝas kaj malnoviĝas estas proksima al malapero."],[9,1,"Sed eĉ la unua interligo havis ordonojn pri Diservado, kaj sanktejon mondan.","Sed eĉ la unua interligo havis ordonojn pri Diservado, kaj sanktejon mondan."],[9,2,"Ĉar tabernaklo estis pretigita: la unua, en kiu estis la kandelabro kaj la tablo kaj la panoj de propono; ĝi estas nomata la Sanktejo;","Ĉar tabernaklo estis pretigita: la unua, en kiu estis la kandelabro kaj la tablo kaj la panoj de propono; ĝi estas nomata la Sanktejo;"],[9,3,"kaj post la dua kurteno, la tabernaklo nomata la Plejsanktejo,","kaj post la dua kurteno, la tabernaklo nomata la Plejsanktejo,"],[9,4,"havanta la oran incensilon, kaj la keston de interligo, tegitan entute per oro, en kiu estis vazo ora (enhavanta la manaon) kaj la ekflorinta bastono de Aaron kaj la tabeloj de la interligo,","havanta la oran incensilon, kaj la keston de interligo, tegitan entute per oro, en kiu estis vazo ora (enhavanta la manaon) kaj la ekflorinta bastono de Aaron kaj la tabeloj de la interligo,"],[9,5,"kaj super tio kerubojn de gloro superombrantajn la fermoplaton, pri kiuj ni nun ne povas detale paroli.","kaj super tio kerubojn de gloro superombrantajn la fermoplaton, pri kiuj ni nun ne povas detale paroli."],[9,6,"Kiam do ĉi tio estis tiel aranĝita, en la unuan tabernaklon eniras ĉiam la pastroj, farante la Diservojn;","Kiam do ĉi tio estis tiel aranĝita, en la unuan tabernaklon eniras ĉiam la pastroj, farante la Diservojn;"],[9,7,"sed en la duan, unufoje en la jaro eniras la ĉefpastro sola, ne sen sango, kiun li oferas pro si kaj pro la eraroj de la popolo;","sed en la duan, unufoje en la jaro eniras la ĉefpastro sola, ne sen sango, kiun li oferas pro si kaj pro la eraroj de la popolo;"],[9,8,"per tio la Sankta Spirito montras, ke la vojo en la sanktejon ankoraŭ ne estas elmontrita, dum la unua tabernaklo ankoraŭ staras;","per tio la Sankta Spirito montras, ke la vojo en la sanktejon ankoraŭ ne estas elmontrita, dum la unua tabernaklo ankoraŭ staras;"],[9,9,"kio estas parabolo por la nuna tempo; laŭ kio estas oferataj donacoj kaj oferoj, kiuj ne povas laŭ la konscienco perfektigi la adoranton,","kio estas parabolo por la nuna tempo; laŭ kio estas oferataj donacoj kaj oferoj, kiuj ne povas laŭ la konscienco perfektigi la adoranton,"],[9,10,"nur altrudate (kun manĝaĵoj kaj trinkaĵoj kaj diversaj lavadoj kaj karnaj purigadoj) ĝis tempo de reformo.","nur altrudate (kun manĝaĵoj kaj trinkaĵoj kaj diversaj lavadoj kaj karnaj purigadoj) ĝis tempo de reformo."],[9,11,"Sed Kristo, aperinte kiel ĉefpastro de la estontaj bonoj, per la pli granda kaj pli perfekta tabernaklo, ne manfarita, tio estas ne el ĉi tiu kreo,","Sed Kristo, aperinte kiel ĉefpastro de la estontaj bonoj, per la pli granda kaj pli perfekta tabernaklo, ne manfarita, tio estas ne el ĉi tiu kreo,"],[9,12,"nek per la sango de kaproj kaj bovidoj, sed per sia propra sango, eniris unufoje por ĉiam en la sanktejon, atinginte eternan elaĉeton.","nek per la sango de kaproj kaj bovidoj, sed per sia propra sango, eniris unufoje por ĉiam en la sanktejon, atinginte eternan elaĉeton."],[9,13,"Ĉar se la sango de kaproj kaj bovoj, kaj la cindro de bovidino, ŝprucigite sur malpurulojn, sanktigas ĝis la purigado de la karno:","Ĉar se la sango de kaproj kaj bovoj, kaj la cindro de bovidino, ŝprucigite sur malpurulojn, sanktigas ĝis la purigado de la karno:"],[9,14,"kiom pli la sango de Kristo, kiu per la eterna Spirito sin oferis senmakula al Dio, purigos vian konsciencon el malvivaj faroj, por servi al la vivanta Dio?","kiom pli la sango de Kristo, kiu per la eterna Spirito sin oferis senmakula al Dio, purigos vian konsciencon el malvivaj faroj, por servi al la vivanta Dio?"],[9,15,"Kaj pro tio li estas interulo de nova testamento, por ke (post kiam morto okazis por la elaĉeto de tiuj pekoj, kiuj estis sub la unua testamento) la vokitoj ricevu la promeson de la eterna heredaĵo.","Kaj pro tio li estas interulo de nova testamento, por ke (post kiam morto okazis por la elaĉeto de tiuj pekoj, kiuj estis sub la unua testamento) la vokitoj ricevu la promeson de la eterna heredaĵo."],[9,16,"Ĉar kiam estas testamento, nepre devas esti la morto de la testamentinto.","Ĉar kiam estas testamento, nepre devas esti la morto de la testamentinto."],[9,17,"Ĉar testamento efektiviĝas rilate mortinton, ĉar ĝi neniam efikas, dum vivas la testamentinto.","Ĉar testamento efektiviĝas rilate mortinton, ĉar ĝi neniam efikas, dum vivas la testamentinto."],[9,18,"Tial ankaŭ la unua testamento ne sen sango dediĉiĝis.","Tial ankaŭ la unua testamento ne sen sango dediĉiĝis."],[9,19,"Ĉar Moseo, parolinte ĉiun ordonon laŭ la leĝo al la tuta popolo, prenis la sangon de bovidoj kaj kaproj, kun akvo kaj lano skarlata kaj hisopo, kaj aspergis la libron mem kaj la tutan popolon,","Ĉar Moseo, parolinte ĉiun ordonon laŭ la leĝo al la tuta popolo, prenis la sangon de bovidoj kaj kaproj, kun akvo kaj lano skarlata kaj hisopo, kaj aspergis la libron mem kaj la tutan popolon,"],[9,20,"dirante: Jen estas la sango de la interligo, kiun Dio ordonis al vi.","dirante: Jen estas la sango de la interligo, kiun Dio ordonis al vi."],[9,21,"Plue li aspergis per la sango la tabernaklon kaj ĉiujn vazojn de la Diservo.","Plue li aspergis per la sango la tabernaklon kaj ĉiujn vazojn de la Diservo."],[9,22,"Kaj laŭ la leĝo, preskaŭ ĉio puriĝas per sango; kaj sen sangoverŝado ne fariĝas absolvo.","Kaj laŭ la leĝo, preskaŭ ĉio puriĝas per sango; kaj sen sangoverŝado ne fariĝas absolvo."],[9,23,"Necese do estis, ke la ekzemploj de la enĉielaj aferoj estu purigitaj per ĉi tiuj, sed la enĉielaj aferoj mem per pli bonaj oferoj, ol ĉi tiuj.","Necese do estis, ke la ekzemploj de la enĉielaj aferoj estu purigitaj per ĉi tiuj, sed la enĉielaj aferoj mem per pli bonaj oferoj, ol ĉi tiuj."],[9,24,"Ĉar eniris Kristo ne en sanktejon manfaritan, ekzemplon de la vera; sed en la ĉielon mem, por aperi antaŭ la vizaĝo de Dio por ni;","Ĉar eniris Kristo ne en sanktejon manfaritan, ekzemplon de la vera; sed en la ĉielon mem, por aperi antaŭ la vizaĝo de Dio por ni;"],[9,25,"nek estas necese, ke li oferu sin ofte, kiel la ĉefpastro eniras en la sanktejon jaron post jaro, kun sango ne propra;","nek estas necese, ke li oferu sin ofte, kiel la ĉefpastro eniras en la sanktejon jaron post jaro, kun sango ne propra;"],[9,26,"alie li devus ofte suferi de post la fondo de la mondo; sed nun unufoje en la fino de la mondaĝoj li aperis, por forigi la pekon per la ofero de si mem.","alie li devus ofte suferi de post la fondo de la mondo; sed nun unufoje en la fino de la mondaĝoj li aperis, por forigi la pekon per la ofero de si mem."],[9,27,"Kaj kiel estas dekretite por homoj unufoje morti, kaj post tio juĝo;","Kaj kiel estas dekretite por homoj unufoje morti, kaj post tio juĝo;"],[9,28,"tiel ankaŭ Kristo, oferite unufoje, por porti la pekojn de multaj, aperos duan fojon, aparte de peko, al tiuj, kiuj lin atendas, por savo.","tiel ankaŭ Kristo, oferite unufoje, por porti la pekojn de multaj, aperos duan fojon, aparte de peko, al tiuj, kiuj lin atendas, por savo."],[10,1,"Ĉar la leĝo, havante ombron de estontaj bonaĵoj, ne la bildon mem de la aferoj, neniam povas, per tiuj samaj oferoj, kiujn oni oferadas senĉese jaron post jaro, perfektigi la tien venantajn.","Ĉar la leĝo, havante ombron de estontaj bonaĵoj, ne la bildon mem de la aferoj, neniam povas, per tiuj samaj oferoj, kiujn oni oferadas senĉese jaron post jaro, perfektigi la tien venantajn."],[10,2,"Ĉar alie ĉu ili ne ĉesus esti oferataj? tial, ke la adorantoj, unufoje purigite, jam ne havus konsciencon pri pekoj.","Ĉar alie ĉu ili ne ĉesus esti oferataj? tial, ke la adorantoj, unufoje purigite, jam ne havus konsciencon pri pekoj."],[10,3,"Sed en tiuj oferoj estas ĉiujara rememorigo pri pekoj.","Sed en tiuj oferoj estas ĉiujara rememorigo pri pekoj."],[10,4,"Ĉar ne eble estas, ke la sango de bovoj kaj kaproj forprenus pekojn.","Ĉar ne eble estas, ke la sango de bovoj kaj kaproj forprenus pekojn."],[10,5,"Tial, venante en la mondon, li diris: Oferojn kaj donacojn Vi ne deziras, Sed korpon Vi preparis por mi;","Tial, venante en la mondon, li diris: Oferojn kaj donacojn Vi ne deziras, Sed korpon Vi preparis por mi;"],[10,6,"Bruloferojn kaj pekoferojn Vi ne ŝatis.","Bruloferojn kaj pekoferojn Vi ne ŝatis."],[10,7,"Tiam mi diris: Jen mi venis (En la rulaĵo de la libro estas skribite pri mi), Por plenumi Vian volon, ho Dio!","Tiam mi diris: Jen mi venis (En la rulaĵo de la libro estas skribite pri mi), Por plenumi Vian volon, ho Dio!"],[10,8,"Antaŭe dirinte: Oferojn kaj donacojn kaj bruloferojn kaj pekoferojn Vi nek deziris nek ŝatis (kiuj estas oferataj laŭ la leĝo),","Antaŭe dirinte: Oferojn kaj donacojn kaj bruloferojn kaj pekoferojn Vi nek deziris nek ŝatis (kiuj estas oferataj laŭ la leĝo),"],[10,9,"tiam li diris: Jen mi venis, por plenumi Vian volon. Li forprenas la unuan, por ke li starigu la duan.","tiam li diris: Jen mi venis, por plenumi Vian volon. Li forprenas la unuan, por ke li starigu la duan."],[10,10,"Laŭ tiu volo ni estas sanktigitaj per la ofero de la korpo de Jesuo Kristo unufoje por ĉiam.","Laŭ tiu volo ni estas sanktigitaj per la ofero de la korpo de Jesuo Kristo unufoje por ĉiam."],[10,11,"Kaj ĉiu pastro staradas ĉiutage, servante kaj oferante ofte la samajn oferojn, kiuj neniam povas forpreni pekojn;","Kaj ĉiu pastro staradas ĉiutage, servante kaj oferante ofte la samajn oferojn, kiuj neniam povas forpreni pekojn;"],[10,12,"sed li, oferinte unu oferon por pekoj por ĉiam, sidiĝis dekstre de Dio;","sed li, oferinte unu oferon por pekoj por ĉiam, sidiĝis dekstre de Dio;"],[10,13,"de nun atendante, ĝis liaj malamikoj fariĝos benketo por liaj piedoj.","de nun atendante, ĝis liaj malamikoj fariĝos benketo por liaj piedoj."],[10,14,"Ĉar per unu ofero li perfektigis ĝis eterneco la sanktigatojn.","Ĉar per unu ofero li perfektigis ĝis eterneco la sanktigatojn."],[10,15,"Kaj la Sankta Spirito ankaŭ atestas al ni; ĉar, dirinte:","Kaj la Sankta Spirito ankaŭ atestas al ni; ĉar, dirinte:"],[10,16,"Jen estas la interligo, kiun Mi faros kun ili Post tiu tempo, diras la Eternulo: Mi metos Miajn leĝojn en ilian internon, Kaj sur ilia koro Mi ilin skribos; li ankaŭ diras:","Jen estas la interligo, kiun Mi faros kun ili Post tiu tempo, diras la Eternulo: Mi metos Miajn leĝojn en ilian internon, Kaj sur ilia koro Mi ilin skribos; li ankaŭ diras:"],[10,17,"Kaj iliajn pekojn kaj malbonaĵojn Mi ne plu rememoros.","Kaj iliajn pekojn kaj malbonaĵojn Mi ne plu rememoros."],[10,18,"Sed kie estas absolvo de ĉi tiuj, ne plu estas oferado pro peko.","Sed kie estas absolvo de ĉi tiuj, ne plu estas oferado pro peko."],[10,19,"Havante do, fratoj, kuraĝon eniri en la plejsanktejon per la sango de Jesuo,","Havante do, fratoj, kuraĝon eniri en la plejsanktejon per la sango de Jesuo,"],[10,20,"per la vojo nova kaj vivanta, kiun li dediĉis por ni, tra la kurteno, tio estas, lia karno,","per la vojo nova kaj vivanta, kiun li dediĉis por ni, tra la kurteno, tio estas, lia karno,"],[10,21,"kaj havante grandan pastron super la domo de Dio,","kaj havante grandan pastron super la domo de Dio,"],[10,22,"ni alproksimiĝu kun sincera koro, en pleneco de fido, kun niaj koroj aspergitaj for de malbona konscienco, kaj kun la korpoj lavitaj per akvo pura;","ni alproksimiĝu kun sincera koro, en pleneco de fido, kun niaj koroj aspergitaj for de malbona konscienco, kaj kun la korpoj lavitaj per akvo pura;"],[10,23,"ni tenu firme la konfeson de nia espero sendekliniĝe; ĉar la promesinto estas fidela;","ni tenu firme la konfeson de nia espero sendekliniĝe; ĉar la promesinto estas fidela;"],[10,24,"kaj ni pripensu unu la alian, por instigi al amo kaj bonaj faroj;","kaj ni pripensu unu la alian, por instigi al amo kaj bonaj faroj;"],[10,25,"ne forlasante nian kunvenadon, kiel estas la kutimo de iuj; sed konsilante unu la alian, kaj des pli forte, ju pli vi vidas la tagon alproksimiĝanta.","ne forlasante nian kunvenadon, kiel estas la kutimo de iuj; sed konsilante unu la alian, kaj des pli forte, ju pli vi vidas la tagon alproksimiĝanta."],[10,26,"Ĉar se, ricevinte la scion de la vero, ni pekos memvole, jam ne restas ofero pro pekoj,","Ĉar se, ricevinte la scion de la vero, ni pekos memvole, jam ne restas ofero pro pekoj,"],[10,27,"sed ia timoplena atendo de juĝo, kaj de fajra kolero, kiu ekstermos la kontraŭulojn.","sed ia timoplena atendo de juĝo, kaj de fajra kolero, kiu ekstermos la kontraŭulojn."],[10,28,"Tiu, kiu malŝatis la leĝon de Moseo, sen kompato mortas ĉe du aŭ tri atestantoj;","Tiu, kiu malŝatis la leĝon de Moseo, sen kompato mortas ĉe du aŭ tri atestantoj;"],[10,29,"kiom pli severan punon, vi opinias, ke meritos tiu, kiu piedpremis la Filon de Dio kaj rigardas kiel ne sanktan la sangon de la interligo, per kiu li estis sanktigita, kaj kiu spitis la Spiriton de graco?","kiom pli severan punon, vi opinias, ke meritos tiu, kiu piedpremis la Filon de Dio kaj rigardas kiel ne sanktan la sangon de la interligo, per kiu li estis sanktigita, kaj kiu spitis la Spiriton de graco?"],[10,30,"Ĉar ni konas Tiun, kiu diris: Ĉe Mi estas venĝo, Mi repagos. Kaj ankaŭ: La Eternulo juĝos Sian popolon.","Ĉar ni konas Tiun, kiu diris: Ĉe Mi estas venĝo, Mi repagos. Kaj ankaŭ: La Eternulo juĝos Sian popolon."],[10,31,"Terure estas fali en la manojn de la vivanta Dio.","Terure estas fali en la manojn de la vivanta Dio."],[10,32,"Sed memoru la antaŭajn tagojn, en kiuj vi, jam allumite, elportis grandan konflikton de suferoj;","Sed memoru la antaŭajn tagojn, en kiuj vi, jam allumite, elportis grandan konflikton de suferoj;"],[10,33,"unuflanke, kiam vi fariĝis spektaklo per riproĉoj kaj doloroj, kaj aliflanke, kiam vi partoprenis kun tiuj, kiuj tian sperton havis.","unuflanke, kiam vi fariĝis spektaklo per riproĉoj kaj doloroj, kaj aliflanke, kiam vi partoprenis kun tiuj, kiuj tian sperton havis."],[10,34,"Ĉar vi kompatis tiujn, kiuj estis en katenoj, kaj ĝoje akceptis la rabadon de via posedaĵo, sciante, ke vi mem havas pli bonan kaj restantan posedaĵon.","Ĉar vi kompatis tiujn, kiuj estis en katenoj, kaj ĝoje akceptis la rabadon de via posedaĵo, sciante, ke vi mem havas pli bonan kaj restantan posedaĵon."],[10,35,"Tial ne forĵetu vian kuraĝon, kiu havas rekompencon grandan.","Tial ne forĵetu vian kuraĝon, kiu havas rekompencon grandan."],[10,36,"Ĉar vi havas bezonon de pacienco, por ke, plenuminte la volon de Dio, vi ricevu la promeson.","Ĉar vi havas bezonon de pacienco, por ke, plenuminte la volon de Dio, vi ricevu la promeson."],[10,37,"Ĉar ankoraŭ iomete da tempo, La venonto venos, kaj ne malfruos.","Ĉar ankoraŭ iomete da tempo, La venonto venos, kaj ne malfruos."],[10,38,"Sed virtulo vivos per sia fideleco; Kaj se li sin tiros malantaŭen, mia spirito ne ĝojos en li.","Sed virtulo vivos per sia fideleco; Kaj se li sin tiros malantaŭen, mia spirito ne ĝojos en li."],[10,39,"Sed ni ne estas el la malantaŭen tiriĝantaj en pereon, sed el la kredantaj por la gajnado de la animo.","Sed ni ne estas el la malantaŭen tiriĝantaj en pereon, sed el la kredantaj por la gajnado de la animo."],[11,1,"Kaj la fido estas realigo de esperataĵoj, provado de aferoj ne vidataj.","Kaj la fido estas realigo de esperataĵoj, provado de aferoj ne vidataj."],[11,2,"Ĉar per tio la antikvuloj ricevis bonan ateston.","Ĉar per tio la antikvuloj ricevis bonan ateston."],[11,3,"Per la fido ni komprenas, ke la mondaĝoj estas kreitaj per vorto de Dio, tiel ke tio, kio estas vidata, ne estas farita el aperantaĵoj.","Per la fido ni komprenas, ke la mondaĝoj estas kreitaj per vorto de Dio, tiel ke tio, kio estas vidata, ne estas farita el aperantaĵoj."],[11,4,"Per la fido Habel oferis al Dio pli bonan oferon ol Kain, per kio li ricevis ateston, ke li estas justa, ĉar Dio atestis pri liaj donacoj; kaj per ĝi li, mortinte, ankoraŭ parolas.","Per la fido Habel oferis al Dio pli bonan oferon ol Kain, per kio li ricevis ateston, ke li estas justa, ĉar Dio atestis pri liaj donacoj; kaj per ĝi li, mortinte, ankoraŭ parolas."],[11,5,"Per la fido Ĥanoĥ estis transportita, por ne vidi morton; kaj li ne estis trovata, ĉar Dio lin transportis; ĉar antaŭ lia transporto estis atestite pri li, ke li plaĉis al Dio;","Per la fido Ĥanoĥ estis transportita, por ne vidi morton; kaj li ne estis trovata, ĉar Dio lin transportis; ĉar antaŭ lia transporto estis atestite pri li, ke li plaĉis al Dio;"],[11,6,"kaj sen fido neeble estas plaĉi al Li; ĉar necese estas, ke tiu, kiu alvenas al Dio, kredu, ke Li ekzistas, kaj ke Li fariĝas rekompencanto al tiuj, kiuj Lin diligente serĉas.","kaj sen fido neeble estas plaĉi al Li; ĉar necese estas, ke tiu, kiu alvenas al Dio, kredu, ke Li ekzistas, kaj ke Li fariĝas rekompencanto al tiuj, kiuj Lin diligente serĉas."],[11,7,"Per la fido Noa, avertite pri la ankoraŭ ne viditaj aferoj, kun pia timo konstruis arkeon por la savado de sia domo; per kio li kondamnis la mondon, kaj fariĝis heredanto de la justeco laŭ fido.","Per la fido Noa, avertite pri la ankoraŭ ne viditaj aferoj, kun pia timo konstruis arkeon por la savado de sia domo; per kio li kondamnis la mondon, kaj fariĝis heredanto de la justeco laŭ fido."],[11,8,"Per la fido Abraham, vokite, obeis eliri en lokon, kiun li estis ricevonta kiel heredaĵon; kaj li eliris, ne sciante, kien li iras.","Per la fido Abraham, vokite, obeis eliri en lokon, kiun li estis ricevonta kiel heredaĵon; kaj li eliris, ne sciante, kien li iras."],[11,9,"Per la fido li fariĝis pasloĝanto en la lando de la promeso, kiel lando fremda, loĝante en tendoj kun Isaak kaj Jakob, kunheredantoj de la sama promeso;","Per la fido li fariĝis pasloĝanto en la lando de la promeso, kiel lando fremda, loĝante en tendoj kun Isaak kaj Jakob, kunheredantoj de la sama promeso;"],[11,10,"ĉar li serĉis la urbon havantan la fundamentojn, kies arĥitekturisto kaj konstruanto estas Dio.","ĉar li serĉis la urbon havantan la fundamentojn, kies arĥitekturisto kaj konstruanto estas Dio."],[11,11,"Per la fido ankaŭ Sara mem ricevis kapablon gravediĝi, eĉ post la ordinara aĝo, ĉar ŝi kredis la Promesinton fidela;","Per la fido ankaŭ Sara mem ricevis kapablon gravediĝi, eĉ post la ordinara aĝo, ĉar ŝi kredis la Promesinton fidela;"],[11,12,"sekve ankaŭ el unu, kaj tiu kvazaŭ malviva, leviĝis tiel multaj, kiel la steloj de la ĉielo laŭnombre, kaj kiel la sablo, kiu estas sur la bordo de la maro, nekalkulebla.","sekve ankaŭ el unu, kaj tiu kvazaŭ malviva, leviĝis tiel multaj, kiel la steloj de la ĉielo laŭnombre, kaj kiel la sablo, kiu estas sur la bordo de la maro, nekalkulebla."],[11,13,"Ĉiuj tiuj mortis en fido, ne ricevinte la promesojn, sed vidinte kaj salutinte ilin de malproksime, kaj konfesinte, ke ili estas fremduloj kaj migrantoj sur la tero.","Ĉiuj tiuj mortis en fido, ne ricevinte la promesojn, sed vidinte kaj salutinte ilin de malproksime, kaj konfesinte, ke ili estas fremduloj kaj migrantoj sur la tero."],[11,14,"Ĉar tiuj, kiuj parolas tiamaniere, konstatas, ke patrolandon ili serĉas.","Ĉar tiuj, kiuj parolas tiamaniere, konstatas, ke patrolandon ili serĉas."],[11,15,"Kaj se ili tenadus en memoro tiun landon, el kiu ili eliris, ili havus ian okazon por reiri.","Kaj se ili tenadus en memoro tiun landon, el kiu ili eliris, ili havus ian okazon por reiri."],[11,16,"Sed nun pli bonan landon ili celas, tio estas, ĉielan; tial Dio ne hontas pri ili, esti nomata ilia Dio; ĉar Li por ili pretigis urbon.","Sed nun pli bonan landon ili celas, tio estas, ĉielan; tial Dio ne hontas pri ili, esti nomata ilia Dio; ĉar Li por ili pretigis urbon."],[11,17,"Per la fido Abraham, provate, oferis Isaakon; tiu, kiu akceptis la promesojn, ekoferis ja sian solenaskiton;","Per la fido Abraham, provate, oferis Isaakon; tiu, kiu akceptis la promesojn, ekoferis ja sian solenaskiton;"],[11,18,"nome tiu, al kiu estis dirite: Per Isaak oni nomos vian idaron;","nome tiu, al kiu estis dirite: Per Isaak oni nomos vian idaron;"],[11,19,"pensante, ke Dio povas relevi lin eĉ el la mortintoj; el kie ankaŭ li en similaĵo lin retrovis.","pensante, ke Dio povas relevi lin eĉ el la mortintoj; el kie ankaŭ li en similaĵo lin retrovis."],[11,20,"Per la fido Isaak benis Jakobon kaj Esavon pri estontaj aferoj.","Per la fido Isaak benis Jakobon kaj Esavon pri estontaj aferoj."],[11,21,"Per la fido Jakob, mortante, benis ĉiun el la filoj de Jozef, kaj adorkliniĝis sur la supro de sia bastono.","Per la fido Jakob, mortante, benis ĉiun el la filoj de Jozef, kaj adorkliniĝis sur la supro de sia bastono."],[11,22,"Per la fido Jozef, ĉe la fino de sia vivo, aludis la foriron de la Izraelidoj, kaj pri siaj ostoj ordonis.","Per la fido Jozef, ĉe la fino de sia vivo, aludis la foriron de la Izraelidoj, kaj pri siaj ostoj ordonis."],[11,23,"Per la fido Moseo, naskiĝinte, estis kaŝata tri monatojn de la gepatroj, ĉar ili vidis la infaneton belega, kaj ne timis la dekreton de la reĝo.","Per la fido Moseo, naskiĝinte, estis kaŝata tri monatojn de la gepatroj, ĉar ili vidis la infaneton belega, kaj ne timis la dekreton de la reĝo."],[11,24,"Per la fido Moseo, plenkreskinte, rifuzis esti nomata filo de filino de Faraono,","Per la fido Moseo, plenkreskinte, rifuzis esti nomata filo de filino de Faraono,"],[11,25,"plivole elektante kunsuferi kun la popolo de Dio, ol havi la kelktempan ĝuadon de peko,","plivole elektante kunsuferi kun la popolo de Dio, ol havi la kelktempan ĝuadon de peko,"],[11,26,"taksante la riproĉon de Kristo pligranda riĉeco ol la trezoroj Egiptaj, ĉar li rigardis al la estonta rekompenco.","taksante la riproĉon de Kristo pligranda riĉeco ol la trezoroj Egiptaj, ĉar li rigardis al la estonta rekompenco."],[11,27,"Per la fido li forlasis Egiptujon, ne timante la koleregon de la reĝo; ĉar li persistis, kiel vidante Tiun, kiu ne estas videbla.","Per la fido li forlasis Egiptujon, ne timante la koleregon de la reĝo; ĉar li persistis, kiel vidante Tiun, kiu ne estas videbla."],[11,28,"Per la fido li observis la Paskon kaj la sangaspergon, por ke la ekstermanto de la unuenaskitoj ne tuŝu ilin.","Per la fido li observis la Paskon kaj la sangaspergon, por ke la ekstermanto de la unuenaskitoj ne tuŝu ilin."],[11,29,"Per la fido li trapasis la Ruĝan Maron kvazaŭ sekteron, kion fari penante, la Egiptoj dronis.","Per la fido li trapasis la Ruĝan Maron kvazaŭ sekteron, kion fari penante, la Egiptoj dronis."],[11,30,"Per la fido la muroj de Jeriĥo falis, ĉirkaŭirite sep tagojn.","Per la fido la muroj de Jeriĥo falis, ĉirkaŭirite sep tagojn."],[11,31,"Per la fido la malĉastistino Raĥab ne pereis kun la nekredantoj, akceptinte la spionojn kun paco.","Per la fido la malĉastistino Raĥab ne pereis kun la nekredantoj, akceptinte la spionojn kun paco."],[11,32,"Kaj kion mi diru plu? ĉar mankus al mi tempo por rakonti pri Gideon kaj Barak kaj Ŝimŝon kaj Jiftaĥ kaj David kaj Samuel kaj la profetoj;","Kaj kion mi diru plu? ĉar mankus al mi tempo por rakonti pri Gideon kaj Barak kaj Ŝimŝon kaj Jiftaĥ kaj David kaj Samuel kaj la profetoj;"],[11,33,"kiuj pere de fido venkis regnojn, plenumis justecon, atingis promesojn, fermis la buŝojn de leonoj,","kiuj pere de fido venkis regnojn, plenumis justecon, atingis promesojn, fermis la buŝojn de leonoj,"],[11,34,"estingis la forton de fajro, forsaviĝis de la tranĉrando de glavo, el malforteco refortiĝis, fariĝis potencaj en militado, forkurigis armeojn de fremduloj.","estingis la forton de fajro, forsaviĝis de la tranĉrando de glavo, el malforteco refortiĝis, fariĝis potencaj en militado, forkurigis armeojn de fremduloj."],[11,35,"Virinoj rericevis siajn mortintojn per revivigo; kaj aliaj suferis turmentadon, ne akceptante liberigon, por atingi pli bonan releviĝon;","Virinoj rericevis siajn mortintojn per revivigo; kaj aliaj suferis turmentadon, ne akceptante liberigon, por atingi pli bonan releviĝon;"],[11,36,"kaj aliaj elproviĝis per mokado kaj skurĝado kaj ankaŭ de katenoj kaj malliberiĝo;","kaj aliaj elproviĝis per mokado kaj skurĝado kaj ankaŭ de katenoj kaj malliberiĝo;"],[11,37,"ili estis ŝtonmortigataj, dissegataj, tentataj; per glavo ili estis mortigitaj; ili ĉirkaŭvagis en ŝafaj kaj kapraj feloj, senigite, subpremate, dolorigate","ili estis ŝtonmortigataj, dissegataj, tentataj; per glavo ili estis mortigitaj; ili ĉirkaŭvagis en ŝafaj kaj kapraj feloj, senigite, subpremate, dolorigate"],[11,38,"(je kiuj la mondo ne estis inda); ili vagadis en dezertoj, sur montoj, en kavernoj kaj kaŝejoj de la tero.","(je kiuj la mondo ne estis inda); ili vagadis en dezertoj, sur montoj, en kavernoj kaj kaŝejoj de la tero."],[11,39,"Kaj ĉiuj tiuj, ricevinte bonan ateston per sia fido, ne ricevis la promeson,","Kaj ĉiuj tiuj, ricevinte bonan ateston per sia fido, ne ricevis la promeson,"],[11,40,"ĉar Dio antaŭvidis por ni ion pli bonan, por ke ili sen ni ne estu perfektigataj.","ĉar Dio antaŭvidis por ni ion pli bonan, por ke ili sen ni ne estu perfektigataj."],[12,1,"Tial ankaŭ ni, havante ĉirkaŭ ni tian nubegon da atestantoj, formetu ĉion pezan kaj la pekon embarasantan, kaj persiste kuru la kuradon antaŭ ni metitan,","Tial ankaŭ ni, havante ĉirkaŭ ni tian nubegon da atestantoj, formetu ĉion pezan kaj la pekon embarasantan, kaj persiste kuru la kuradon antaŭ ni metitan,"],[12,2,"direktante la rigardon al la aŭtoro kaj perfektiganto de la fido, Jesuo, kiu, pro la ĝojo antaŭ li metita, suferis la krucon, malestimante honton, kaj sidiĝis dekstre de la trono de Dio.","direktante la rigardon al la aŭtoro kaj perfektiganto de la fido, Jesuo, kiu, pro la ĝojo antaŭ li metita, suferis la krucon, malestimante honton, kaj sidiĝis dekstre de la trono de Dio."],[12,3,"Ĉar pripensu tiun, kiu suferis tian kontraŭdiradon de pekuloj kontraŭ li, por ke vi ne laciĝu kaj ne malfortiĝu en viaj spiritoj.","Ĉar pripensu tiun, kiu suferis tian kontraŭdiradon de pekuloj kontraŭ li, por ke vi ne laciĝu kaj ne malfortiĝu en viaj spiritoj."],[12,4,"Vi ankoraŭ ne kontraŭstaris ĝis sango, batalante kontraŭ peko;","Vi ankoraŭ ne kontraŭstaris ĝis sango, batalante kontraŭ peko;"],[12,5,"kaj vi forgesis la admonon, kiu rezonas kun vi, kiel kun filoj: Mia filo, ne malŝatu la punon de la Eternulo, Nek svenu, riproĉate de Li;","kaj vi forgesis la admonon, kiu rezonas kun vi, kiel kun filoj: Mia filo, ne malŝatu la punon de la Eternulo, Nek svenu, riproĉate de Li;"],[12,6,"Ĉar kiun la Eternulo amas, tiun Li punkorektas, Kaj Li skurĝas ĉiun filon, kiun Li akceptas.","Ĉar kiun la Eternulo amas, tiun Li punkorektas, Kaj Li skurĝas ĉiun filon, kiun Li akceptas."],[12,7,"Se vi suferas punon, kiel al filoj Dio rilatiĝas al vi; ĉar kia filo estas, kiun la patro ne punas?","Se vi suferas punon, kiel al filoj Dio rilatiĝas al vi; ĉar kia filo estas, kiun la patro ne punas?"],[12,8,"Sed se vi estas sen puno, en kiu ĉiuj fariĝas partoprenantoj, tiuokaze vi estas bastardoj, kaj ne filoj.","Sed se vi estas sen puno, en kiu ĉiuj fariĝas partoprenantoj, tiuokaze vi estas bastardoj, kaj ne filoj."],[12,9,"Cetere ni havis patrojn de nia karno, kiuj nin punis, kaj ni respektis ilin; ĉu ni ne multe pli submetiĝu al la Patro de la spiritoj, kaj vivu?","Cetere ni havis patrojn de nia karno, kiuj nin punis, kaj ni respektis ilin; ĉu ni ne multe pli submetiĝu al la Patro de la spiritoj, kaj vivu?"],[12,10,"Ĉar ili ja dum kelke da tagoj laŭ sia volo punis; sed Li, por utilo, por ke ni partoprenu en Lia sankteco.","Ĉar ili ja dum kelke da tagoj laŭ sia volo punis; sed Li, por utilo, por ke ni partoprenu en Lia sankteco."],[12,11,"Ĉiu puno portempe ŝajnas esti ne ĝoja, sed malĝoja; sed poste ĝi donas la pacplenan frukton de justeco al tiuj, kiuj per ĝi estas ekzercitaj.","Ĉiu puno portempe ŝajnas esti ne ĝoja, sed malĝoja; sed poste ĝi donas la pacplenan frukton de justeco al tiuj, kiuj per ĝi estas ekzercitaj."],[12,12,"Tial levu la manojn pendantajn kaj la senfortajn genuojn;","Tial levu la manojn pendantajn kaj la senfortajn genuojn;"],[12,13,"kaj faru rektajn vojetojn por viaj piedoj, por ke tio, kio estas lama, ne deturniĝu, sed prefere resaniĝu.","kaj faru rektajn vojetojn por viaj piedoj, por ke tio, kio estas lama, ne deturniĝu, sed prefere resaniĝu."],[12,14,"Serĉu pacon kun ĉiuj, kaj la sanktigon, sen kiu neniu vidos la Sinjoron;","Serĉu pacon kun ĉiuj, kaj la sanktigon, sen kiu neniu vidos la Sinjoron;"],[12,15,"rigardante zorge, por ke neniu maltrafu la gracon de Dio, por ke nenia radiko de maldolĉeco, altkreskante, vin ĝenu, kaj por ke per tio multaj ne malpuriĝu;","rigardante zorge, por ke neniu maltrafu la gracon de Dio, por ke nenia radiko de maldolĉeco, altkreskante, vin ĝenu, kaj por ke per tio multaj ne malpuriĝu;"],[12,16,"por ke ne estu iu malĉastulo aŭ malpiulo, kiel Esav, kiu por unu manĝo vendis sian unuenaskitecon.","por ke ne estu iu malĉastulo aŭ malpiulo, kiel Esav, kiu por unu manĝo vendis sian unuenaskitecon."],[12,17,"Ĉar vi scias, ke eĉ kiam li poste deziris heredi la benon, li estis rifuzita; ĉar por pentado li trovis nenian lokon, kvankam kun larmoj li ĝin serĉis.","Ĉar vi scias, ke eĉ kiam li poste deziris heredi la benon, li estis rifuzita; ĉar por pentado li trovis nenian lokon, kvankam kun larmoj li ĝin serĉis."],[12,18,"Ĉar vi ne alvenis al monto tuŝebla kaj brulanta per fajro, kaj al nigreco kaj mallumo kaj ventego,","Ĉar vi ne alvenis al monto tuŝebla kaj brulanta per fajro, kaj al nigreco kaj mallumo kaj ventego,"],[12,19,"kaj sono de trumpeto kaj voĉo de paroloj, kies aŭdantoj petegis, ke plua vorto ne estu parolata al ili,","kaj sono de trumpeto kaj voĉo de paroloj, kies aŭdantoj petegis, ke plua vorto ne estu parolata al ili,"],[12,20,"ĉar ili ne povis elporti la ordonon: Se eĉ bruto tuŝos la monton, ĝi estu ŝtonmortigita;","ĉar ili ne povis elporti la ordonon: Se eĉ bruto tuŝos la monton, ĝi estu ŝtonmortigita;"],[12,21,"kaj tiel terura estis la aperaĵo, ke Moseo diris: Mi timegas kaj tremas;","kaj tiel terura estis la aperaĵo, ke Moseo diris: Mi timegas kaj tremas;"],[12,22,"sed vi alvenis al la monto Cion kaj al la urbo de vivanta Dio, la ĉiela Jerusalem, kaj al miriadoj da anĝeloj,","sed vi alvenis al la monto Cion kaj al la urbo de vivanta Dio, la ĉiela Jerusalem, kaj al miriadoj da anĝeloj,"],[12,23,"al la ĝenerala kunveno kaj eklezio de la unuenaskitoj, en la ĉielo enskribitaj, kaj al Dio, la Juĝisto de ĉiuj, kaj al la spiritoj de justuloj perfektigitaj,","al la ĝenerala kunveno kaj eklezio de la unuenaskitoj, en la ĉielo enskribitaj, kaj al Dio, la Juĝisto de ĉiuj, kaj al la spiritoj de justuloj perfektigitaj,"],[12,24,"kaj al Jesuo, la interulo de nova interligo, kaj al la sango de aspergo, kiu parolas pli bonajn aferojn ol la sango de Habel.","kaj al Jesuo, la interulo de nova interligo, kaj al la sango de aspergo, kiu parolas pli bonajn aferojn ol la sango de Habel."],[12,25,"Gardu vin, ke vi ne forrifuzu la parolanton. Ĉar se ne forsaviĝis tiuj, kiuj forrifuzis la admonanton sur la tero, des malpli ni, deturnante nin de la parolanto el la ĉielo,","Gardu vin, ke vi ne forrifuzu la parolanton. Ĉar se ne forsaviĝis tiuj, kiuj forrifuzis la admonanton sur la tero, des malpli ni, deturnante nin de la parolanto el la ĉielo,"],[12,26,"kies voĉo tiam skuis la teron; sed nun Li promesis, dirante: Ankoraŭ unufoje Mi ekmovos ne sole la teron, sed ankaŭ la ĉielon.","kies voĉo tiam skuis la teron; sed nun Li promesis, dirante: Ankoraŭ unufoje Mi ekmovos ne sole la teron, sed ankaŭ la ĉielon."],[12,27,"Kaj tiu diro: Ankoraŭ unufoje — montras la translokigon de la skuitaĵoj, kiel de faritaĵoj, por ke la neskueblaj restu.","Kaj tiu diro: Ankoraŭ unufoje — montras la translokigon de la skuitaĵoj, kiel de faritaĵoj, por ke la neskueblaj restu."],[12,28,"Tial, ricevante regnon neskueblan, ni havu dankemecon, per kiu ni adoru Dion akcepteble kun respektego kaj pia timo;","Tial, ricevante regnon neskueblan, ni havu dankemecon, per kiu ni adoru Dion akcepteble kun respektego kaj pia timo;"],[12,29,"ĉar nia Dio estas fajro konsumanta.","ĉar nia Dio estas fajro konsumanta."],[13,1,"La fratamo daŭradu.","La fratamo daŭradu."],[13,2,"Ne forgesu gastamon al nekonatoj; ĉar per tio iuj gastigis anĝelojn, ne sciante.","Ne forgesu gastamon al nekonatoj; ĉar per tio iuj gastigis anĝelojn, ne sciante."],[13,3,"Memoru la katenitojn, kvazaŭ vi ankaŭ estus katenitaj, kaj la suferantojn, ĉar vi ankaŭ estas en la korpo.","Memoru la katenitojn, kvazaŭ vi ankaŭ estus katenitaj, kaj la suferantojn, ĉar vi ankaŭ estas en la korpo."],[13,4,"Estu honorata la edzeco ĉe ĉiuj, kaj la lito estu senmakula; ĉar malĉastulojn kaj adultulojn Dio juĝos.","Estu honorata la edzeco ĉe ĉiuj, kaj la lito estu senmakula; ĉar malĉastulojn kaj adultulojn Dio juĝos."],[13,5,"Estu via karaktero sen monamo; estu kontentaj je tio, kion vi havas; ĉar Li mem diris: Mi ne foriros de vi kaj ne forlasos vin.","Estu via karaktero sen monamo; estu kontentaj je tio, kion vi havas; ĉar Li mem diris: Mi ne foriros de vi kaj ne forlasos vin."],[13,6,"Tial ni kuraĝas diri: La Eternulo estas mia helpanto, mi ne timos; Kion faros al mi homo?","Tial ni kuraĝas diri: La Eternulo estas mia helpanto, mi ne timos; Kion faros al mi homo?"],[13,7,"Memoru viajn regintojn, kiuj parolis al vi la vorton de Dio; kaj ilian fidon imitu, pripensante la finon de ilia vivmaniero.","Memoru viajn regintojn, kiuj parolis al vi la vorton de Dio; kaj ilian fidon imitu, pripensante la finon de ilia vivmaniero."],[13,8,"Jesuo Kristo estas la sama hieraŭ, hodiaŭ, kaj ĝis eterneco.","Jesuo Kristo estas la sama hieraŭ, hodiaŭ, kaj ĝis eterneco."],[13,9,"Ne forportiĝu per dogmaroj diversaj kaj fremdaj; ĉar estas bone, ke la koro estu plifortigata per graco, ne per manĝaĵoj, per kiuj ne profitis la okupiĝantaj pri ili.","Ne forportiĝu per dogmaroj diversaj kaj fremdaj; ĉar estas bone, ke la koro estu plifortigata per graco, ne per manĝaĵoj, per kiuj ne profitis la okupiĝantaj pri ili."],[13,10,"Ni havas altaron, el kiu la servantoj de la tabernaklo havas nenian rajton manĝi.","Ni havas altaron, el kiu la servantoj de la tabernaklo havas nenian rajton manĝi."],[13,11,"Ĉar la korpoj de tiuj bestoj, kies sango estas en la sanktejon enportata de la ĉefpastro pro peko, estas bruligataj ekster la tendaro.","Ĉar la korpoj de tiuj bestoj, kies sango estas en la sanktejon enportata de la ĉefpastro pro peko, estas bruligataj ekster la tendaro."],[13,12,"Tial Jesuo ankaŭ, por ke li sanktigu la popolon per sia propra sango, ekster la pordego suferis.","Tial Jesuo ankaŭ, por ke li sanktigu la popolon per sia propra sango, ekster la pordego suferis."],[13,13,"Tial ni eliru al li ekster la tendaro, portante lian riproĉon.","Tial ni eliru al li ekster la tendaro, portante lian riproĉon."],[13,14,"Ĉar ĉi tie ni ne havas restantan urbon, sed estontan ni serĉas.","Ĉar ĉi tie ni ne havas restantan urbon, sed estontan ni serĉas."],[13,15,"Per li do ni oferu al Dio ĉiam oferon de laŭdo, tio estas, la frukton de niaj lipoj konfesantaj al lia nomo.","Per li do ni oferu al Dio ĉiam oferon de laŭdo, tio estas, la frukton de niaj lipoj konfesantaj al lia nomo."],[13,16,"Sed ne forgesu la bonfaradon kaj kunulecon; ĉar tiaj oferoj plaĉas al Dio.","Sed ne forgesu la bonfaradon kaj kunulecon; ĉar tiaj oferoj plaĉas al Dio."],[13,17,"Obeu al tiuj, kiuj vin regas, kaj submetiĝu; ĉar ili viglas pro viaj animoj, kvazaŭ liveronte raporton; por ke kun ĝojo ili faru tion, kaj ne ĝemante, ĉar ĉi tio estus senprofita por vi.","Obeu al tiuj, kiuj vin regas, kaj submetiĝu; ĉar ili viglas pro viaj animoj, kvazaŭ liveronte raporton; por ke kun ĝojo ili faru tion, kaj ne ĝemante, ĉar ĉi tio estus senprofita por vi."],[13,18,"Preĝu por ni; ĉar ni fidas, ke ni havas bonan konsciencon, dezirante en ĉio honeste vivi.","Preĝu por ni; ĉar ni fidas, ke ni havas bonan konsciencon, dezirante en ĉio honeste vivi."],[13,19,"Sed des pli urĝe mi petegas vin fari tion, por ke mi tiom pli frue estu redonata al vi.","Sed des pli urĝe mi petegas vin fari tion, por ke mi tiom pli frue estu redonata al vi."],[13,20,"Nun la Dio de paco, kiu relevis el la mortintoj la grandan paŝtiston de la ŝafoj, nian Sinjoron Jesuo, per la sango de la eterna interligo,","Nun la Dio de paco, kiu relevis el la mortintoj la grandan paŝtiston de la ŝafoj, nian Sinjoron Jesuo, per la sango de la eterna interligo,"],[13,21,"perfektigu vin en ĉia bona laboro, por plenumi Lian volon, farante en vi tion, kio plaĉas al Li, per Jesuo Kristo, al kiu estu la gloro por ĉiam kaj eterne. Amen.","perfektigu vin en ĉia bona laboro, por plenumi Lian volon, farante en vi tion, kio plaĉas al Li, per Jesuo Kristo, al kiu estu la gloro por ĉiam kaj eterne. Amen."],[13,22,"Kaj mi petegas vin, fratoj, toleru la vorton de konsilo, ĉar mi skribis al vi per malmulte da vortoj.","Kaj mi petegas vin, fratoj, toleru la vorton de konsilo, ĉar mi skribis al vi per malmulte da vortoj."],[13,23,"Sciu, ke estas liberigita nia frato Timoteo, kun kiu, se li venos baldaŭ, mi vin vidos.","Sciu, ke estas liberigita nia frato Timoteo, kun kiu, se li venos baldaŭ, mi vin vidos."],[13,24,"Salutu ĉiujn, kiuj vin regas, kaj ĉiujn sanktulojn. Tiuj, kiuj estas el Italujo, vin salutas.","Salutu ĉiujn, kiuj vin regas, kaj ĉiujn sanktulojn. Tiuj, kiuj estas el Italujo, vin salutas."],[13,25,"Graco estu kun vi ĉiuj. Amen.","Graco estu kun vi ĉiuj. Amen."]]}};